/* MathQuest — Éducation aux médias et à l'information (EMI) au collège, année scolaire 2026-2027 : 24 chapitres reconstruits (emi6a…emi3f).
   Cadre légal : loi n°2013-595 du 8 juillet 2013 d'orientation et de programmation pour la refondation de l'École de la République,
   qui inscrit l'éducation aux médias et à l'information dans le Code de l'éducation ; le CLEMI (Centre pour l'éducation aux médias
   et à l'information), organisme chargé de cette mission dans tout le système scolaire, est régi par les articles D. 314-99 à
   D. 314-105 du Code de l'éducation. Le CLEMI structure l'EMI autour de plusieurs « cultures » complémentaires (culture médiatique,
   culture informationnelle, culture sociale et citoyenne, culture technique et numérique) déclinées en repères annuels de progressivité.
   Références complémentaires selon les chapitres : loi du 29 juillet 1881 sur la liberté de la presse ; Code de la propriété
   intellectuelle (droit d'auteur) ; RGPD (2018) et CNIL (données personnelles) ; Éduscol — ressources EMI. */
(function(){
'use strict';
const MQ=window.MQCollege;if(!MQ)return;const H=MQ.H;
const {R,P,ch,num,txt,order,tf,bank,pairs,sort,seq,mix,pickN,shuffle,nf}=H;
const C=(d,u,ex,m,a,r)=>({d,u,ex,m,a,r});const T=(t,h)=>({t,h});
const LOI2013='Loi n°2013-595 du 8 juillet 2013 d’orientation et de programmation pour la refondation de l’École de la République (EMI inscrite au Code de l’éducation)';
const CLEMI='CLEMI — Centre pour l’éducation aux médias et à l’information (articles D. 314-99 à D. 314-105 du Code de l’éducation)';
const REF_CLEMI='CLEMI — référentiel de compétences en éducation aux médias et à l’information (cultures médiatique, informationnelle, sociale et citoyenne, technique et numérique)';
const LOI1881='Loi du 29 juillet 1881 sur la liberté de la presse';
const CPI='Code de la propriété intellectuelle (droit d’auteur)';
const EDU='Éduscol — ressources d’éducation aux médias et à l’information (eduscol.education.gouv.fr)';

MQ.add('emi','6',[
{id:'emi6a',name:'Identifier une source d’information',icon:'🔖',domain:'Information',
 refs:[REF_CLEMI+' — culture informationnelle',LOI2013,EDU],
 tip:'Avant de croire une information, demande-toi : QUI la donne ? Un auteur identifié (journaliste, scientifique, institution) est plus sérieux qu’un message anonyme.',
 c:C(`Tous les jours, des informations arrivent par la télévision, un site, une application, un message d’un ami. Savoir d’où vient une information — sa <b>source</b> — est la première étape pour juger si elle est sérieuse.`,
  [T('Qu’est-ce qu’une source ?',`<p>La <b>source</b> d’une information, c’est son origine : qui l’a écrite, filmée ou dite, et où elle a été publiée. Une source peut être un <b>journal</b>, une <b>agence de presse</b>, un <b>site institutionnel</b>, un témoin, mais aussi un message anonyme ou une rumeur.</p><p>On distingue la <b>source primaire</b> (celle qui a observé ou produit l’information en premier) et la <b>source secondaire</b> (qui la rapporte, parfois en la résumant ou en la commentant).</p>`),
   T('Repérer les indices',`<p>Pour juger une source : le <b>nom de l’auteur</b> apparaît-il ? Le <b>site</b> est-il connu et sérieux ? Y a-t-il une <b>date</b> ? L’information est-elle <b>reprise</b> par d’autres médias fiables ? L’absence de ces indices doit rendre prudent.</p>`)],
  [{q:'Un message sans nom d’auteur circule sur un groupe de discussion, annonçant une fausse alerte. Que faire ?',s:['Chercher qui est à l’origine du message : personne n’est identifié.','Vérifier si un média connu en parle : aucun ne le confirme.','Ne pas transférer le message tant qu’il n’est pas confirmé par une source fiable.']}],
  ['Je repère qui a produit l’information.','Je distingue source primaire et source secondaire.','Je vérifie la présence d’un auteur et d’une date.','Je me méfie d’un message sans source identifiable.'],
  ['Croire une information simplement parce qu’elle circule beaucoup.','Confondre un témoin direct et quelqu’un qui répète une rumeur.','Transférer un message sans en vérifier l’origine.'],
  ['Source = origine de l’information.','Primaire (premier témoin) vs secondaire (qui rapporte).','Indices de fiabilité : auteur, date, site.']),
 g:mix([sort({'Source primaire':['un journaliste présent sur les lieux d’un événement','une photo prise par un témoin direct','un communiqué officiel d’une mairie'],'Source secondaire':['un article qui résume un reportage d’un autre média','une personne qui raconte ce qu’elle a entendu dire','un message qui recopie une information déjà publiée ailleurs']},{q:'« %s » est une source…'}),2],
  [bank([
   ['Qu’est-ce qu’une source d’information ?','son origine : qui l’a produite et où elle a été publiée',['sa longueur','sa couleur','son nombre de partages'],'On remonte toujours à l’origine.'],
   ['Un message sans nom d’auteur ni date est…','moins fiable, car on ne peut pas vérifier son origine',['toujours fiable','automatiquement faux','sans importance'],'L’absence d’indices doit alerter.'],
   ['Une source primaire est…','celle qui a observé ou produit l’information en premier',['celle qui la commente seulement','la première personne à la partager en ligne','n’importe quel site'],'Un témoin direct, par exemple.'],
   ['Pourquoi vérifier si une information est reprise par plusieurs médias fiables ?','cela renforce sa crédibilité',['cela la rend automatiquement fausse','ce n’est jamais utile','cela ne change rien'],'Plusieurs sources sérieuses confirment mieux qu’une seule.'],
   ['Un communiqué officiel d’une mairie sur les horaires d’une piscine est…','une source primaire fiable',['une rumeur','une opinion','une publicité'],'L’organisme concerné est la source directe.'],
   ['Avant de croire une information surprenante, il faut d’abord…','chercher qui en est à l’origine',['la partager immédiatement','l’oublier tout de suite','y croire sans vérifier'],'Identifier la source est la première étape.'],
   ['Le fait qu’une information soit partagée de nombreuses fois prouve-t-il qu’elle est vraie ?','non',['oui, toujours','oui, après 100 partages','oui, si elle vient d’un ami'],'La popularité ne garantit pas la véracité.'],
   {tf:'Toute information trouvée sur Internet a forcément un auteur identifiable.',v:false,e:'Beaucoup de messages circulent sans source claire.'},
   {tf:'Une agence de presse est une source souvent utilisée par plusieurs journaux.',v:true,e:'Elle fournit des informations vérifiées à de nombreux médias.',d:2},
   ['Un témoin direct d’un événement est…','une source primaire',['une source secondaire','jamais fiable','une rumeur obligatoirement'],'Il a observé l’événement lui-même.',2]]),2])},

{id:'emi6b',name:'Distinguer fait, opinion et publicité',icon:'💭',domain:'Esprit critique',
 refs:[REF_CLEMI+' — culture médiatique et informationnelle',EDU],
 tip:'Un fait se vérifie (« il a plu hier à Paris »), une opinion se discute (« ce film est le meilleur de l’année »), une publicité cherche à vendre.',
 c:C(`Dans un article, une vidéo ou une conversation, trois types de contenus se mélangent souvent : les <b>faits</b> (vérifiables), les <b>opinions</b> (des avis) et les <b>publicités</b> (qui veulent vendre). Les distinguer évite de confondre une impression personnelle avec une vérité établie.`,
  [T('Fait et opinion',`<p>Un <b>fait</b> est une information qu’on peut vérifier : « Le match a eu lieu le 5 octobre. » Une <b>opinion</b> exprime un jugement personnel : « C’était le plus beau match de la saison. » Les deux peuvent apparaître dans la même phrase, mais seul le fait peut être prouvé vrai ou faux.</p>`),
   T('La publicité',`<p>Une <b>publicité</b> cherche à <b>vendre</b> un produit, un service ou une idée. Elle est parfois clairement indiquée (« Publicité », « Sponsorisé »), parfois plus discrète (placement de produit, influenceur rémunéré). Elle présente souvent le produit sous son meilleur jour, sans en dire les inconvénients.</p>`)],
  [{q:'Une vidéo dit : « Ce jeu vidéo est sorti le 3 octobre. C’est le meilleur jeu de l’année ! Achetez-le vite ! »',s:['« Sorti le 3 octobre » est un fait vérifiable.','« C’est le meilleur jeu de l’année » est une opinion.','« Achetez-le vite » ressemble à de la publicité.']}],
  ['Je distingue un fait vérifiable d’une opinion.','Je repère les mentions « Publicité » ou « Sponsorisé ».','Je reste attentif aux publicités moins visibles.','Je ne confonds pas un avis avec une vérité.'],
  ['Croire qu’une opinion répétée devient un fait.','Ignorer qu’un influenceur peut être payé pour présenter un produit.','Confondre présentation avantageuse et information complète.'],
  ['Fait = vérifiable. Opinion = avis.','Publicité : vendre, parfois signalée, parfois discrète.','Rester attentif aux deux.']),
 g:mix([sort({'Fait':['Le film dure 120 minutes.','Le magasin ouvre à 9 heures.','Il y a eu 30 buts marqués ce week-end.'],'Opinion':['Ce film est ennuyeux.','Ce magasin a les meilleurs produits.','Ce joueur est le meilleur de l’équipe.']},{q:'« %s » est…'}),2],
  [bank([
   ['Un fait se caractérise par le fait qu’il…','peut être vérifié',['ne peut jamais être vérifié','est toujours agréable','est toujours négatif'],'On peut prouver qu’il est vrai ou faux.'],
   ['Une opinion exprime…','un avis personnel',['une vérité absolue','un chiffre exact','une loi'],'Elle peut être discutée.'],
   ['Une mention « Sponsorisé » sur une vidéo indique…','que le créateur a été payé pour en parler',['que la vidéo est gratuite','que la vidéo est fausse','qu’il n’y a aucun lien commercial'],'C’est une forme de publicité.'],
   ['Un influenceur qui présente un produit sans préciser qu’il est payé pour cela fait…','une publicité non signalée, ce qui est contestable',['une information neutre et fiable','un fait vérifiable','une opinion sans conséquence'],'La transparence sur les partenariats est importante.',2],
   ['« Ce téléphone a une belle couleur » est…','une opinion',['un fait','une publicité obligatoirement','une loi'],'C’est un jugement personnel sur l’esthétique.'],
   ['« Ce téléphone pèse 180 grammes » est…','un fait',['une opinion','une publicité','une rumeur'],'C’est une donnée mesurable.'],
   ['Une publicité présente généralement un produit…','sous son meilleur jour, sans en dire les inconvénients',['de façon totalement neutre','en citant tous ses défauts','sans jamais chercher à convaincre'],'Son but est de vendre.'],
   {tf:'Une phrase peut mélanger un fait et une opinion.',v:true,e:'Exemple : « Le film dure 2 heures (fait) et c’est trop long (opinion). »'},
   {tf:'Toutes les publicités sont clairement signalées comme telles.',v:false,e:'Certaines formes de publicité sont plus discrètes (placement de produit).',d:2}]),3])},

{id:'emi6c',name:'Comprendre le rôle des médias',icon:'📰',domain:'Médias',
 refs:[REF_CLEMI+' — culture médiatique',LOI1881,EDU],
 tip:'Informer, mais aussi vérifier avant de publier : c’est le travail du journaliste, différent de celui d’un internaute qui partage sans vérifier.',
 c:C(`La presse écrite, la radio, la télévision et les sites d’information sont des <b>médias</b>. Leur rôle est d’informer le public, mais ils fonctionnent selon des règles et des métiers précis, encadrés notamment par la <b>liberté de la presse</b>.`,
  [T('Les métiers de l’information',`<p>Le <b>journaliste</b> enquête, vérifie et rédige l’information ; le <b>rédacteur en chef</b> organise le contenu d’un média ; la <b>rédaction</b> est l’équipe qui produit les articles ou les reportages. Un média applique une <b>ligne éditoriale</b> : les choix de sujets et le ton qu’il adopte.</p>`),
   T('La liberté de la presse',`<p>En France, la <b>liberté de la presse</b> est garantie par la loi du 29 juillet 1881 : les médias peuvent informer sans être censurés par l’État, mais ils doivent respecter certaines règles (ne pas diffamer, ne pas appeler à la violence). Cette liberté est une condition de la <b>démocratie</b> : elle permet aux citoyens de s’informer librement.</p>`)],
  [{q:'Un journal publie un article sur un sujet sensible, après enquête et vérification. En quoi diffère-t-il d’un simple message partagé en ligne sans vérification ?',s:['Le journaliste a enquêté et vérifié ses informations.','Le média applique des règles professionnelles (rédaction, relecture).','Un message non vérifié n’a suivi aucune de ces étapes.']}],
  ['Je connais le rôle du journaliste.','Je comprends ce qu’est une ligne éditoriale.','Je connais le principe de la liberté de la presse.','Je distingue un média professionnel d’un simple partage non vérifié.'],
  ['Croire que tout message en ligne suit les mêmes règles qu’un média professionnel.','Penser que la liberté de la presse autorise tout sans aucune limite.','Ignorer qu’un média a une ligne éditoriale.'],
  ['Journaliste : enquête et vérifie.','Ligne éditoriale.','Liberté de la presse : loi de 1881, condition de la démocratie.']),
 g:mix([bank([
  ['Le rôle principal d’un journaliste est…','d’enquêter, de vérifier et de rédiger l’information',['de partager sans vérifier','de vendre des produits','de donner uniquement son avis'],'Son métier suit des règles professionnelles.'],
  ['La ligne éditoriale d’un média désigne…','ses choix de sujets et son ton général',['le nombre de ses lecteurs','la couleur de son logo','le prix de ses journaux'],'Elle oriente le contenu publié.'],
  ['La liberté de la presse est garantie par…','la loi du 29 juillet 1881',['un règlement intérieur de collège','une décision d’un seul journal','aucune loi particulière'],'C’est un texte fondateur en France.'],
  ['La liberté de la presse permet…','d’informer sans être censuré par l’État, dans le respect de la loi',['de publier n’importe quoi sans aucune limite','de ne jamais vérifier une information','de censurer les citoyens'],'Elle a des limites légales (diffamation, appel à la violence…).'],
  ['Pourquoi la liberté de la presse est-elle importante pour la démocratie ?','elle permet aux citoyens de s’informer librement',['elle n’a aucun lien avec la démocratie','elle sert uniquement les journalistes','elle empêche toute information'],'S’informer librement est un droit démocratique.',2],
  ['Un rédacteur en chef…','organise le contenu d’un média',['vend des publicités uniquement','répare les ordinateurs de la rédaction','n’a aucun rôle particulier'],'Il coordonne l’équipe de rédaction.'],
  ['Un message partagé en ligne sans vérification est-il soumis aux mêmes règles professionnelles qu’un article de presse ?','non',['oui, exactement les mêmes','oui, car tout est pareil sur Internet','oui, par la loi de 1881 uniquement'],'Les médias professionnels suivent des procédures de vérification.',2],
  {tf:'La liberté de la presse autorise de diffamer n’importe qui sans conséquence.',v:false,e:'La diffamation reste interdite et punie par la loi.'},
  {tf:'Différents médias peuvent avoir des lignes éditoriales différentes sur un même sujet.',v:true,e:'Cela explique parfois des angles de traitement différents.',d:2},
  ['La diffamation consiste à…','porter atteinte à l’honneur ou à la réputation de quelqu’un par des propos faux',['informer de façon neutre','citer une source fiable','exprimer une opinion argumentée'],'Elle est interdite par la loi, même pour un média.',2],
  ['Un reportage diffère d’une simple opinion partagée en ligne parce qu’il…','repose sur une enquête et une vérification des faits',['est toujours plus court','est automatiquement vrai sans vérification','ne contient jamais d’images'],'Le travail journalistique suit une méthode.'],
  ['Qui compose généralement la rédaction d’un média ?','l’équipe de journalistes qui produit les articles ou reportages',['uniquement les lecteurs','uniquement les propriétaires du média','personne en particulier'],'C’est l’équipe chargée du contenu.']]),3])},

{id:'emi6d',name:'Rechercher efficacement sur le Web',icon:'🔍',domain:'Recherche',
 refs:[REF_CLEMI+' — culture informationnelle et technique',EDU],
 tip:'Des mots-clés précis valent mieux qu’une phrase entière : « climat Antarctique fonte glaciers » plutôt que « je voudrais savoir ce qui se passe avec le climat en Antarctique ».',
 c:C(`Chercher une information sur le Web ne se limite pas à taper une question dans un moteur de recherche : il faut choisir ses <b>mots-clés</b>, comprendre les <b>résultats</b> affichés et <b>vérifier</b> ce qu’on trouve.`,
  [T('Choisir ses mots-clés',`<p>Un moteur de recherche trouve des pages contenant les mots demandés : des <b>mots-clés</b> précis donnent de meilleurs résultats qu’une phrase longue. On peut affiner avec des guillemets pour une expression exacte, ou exclure un mot avec un signe « - ».</p>`),
   T('Lire la page de résultats',`<p>La page de résultats affiche titre, adresse et extrait de chaque lien. Certains résultats sont des <b>annonces publicitaires</b> (souvent signalées). On compare plusieurs résultats avant de choisir une page, en regardant la fiabilité du site (voir le chapitre « Identifier une source »).</p>`)],
  [{q:'Pour un exposé sur le volcan islandais Eyjafjöll, quels mots-clés choisir ?',s:['Mots-clés précis : « Eyjafjöll éruption 2010 ».','Éviter une phrase entière avec des mots inutiles.','Vérifier ensuite la fiabilité des pages trouvées.']}],
  ['Je choisis des mots-clés précis.','Je sais utiliser les guillemets pour une expression exacte.','Je repère les annonces publicitaires dans les résultats.','Je compare plusieurs sources avant de conclure.'],
  ['Taper une phrase entière avec des mots inutiles.','Cliquer sur une annonce sans savoir que c’est de la publicité.','Se contenter du tout premier résultat sans vérifier.'],
  ['Mots-clés précis.','Guillemets = expression exacte.','Annonces ≠ résultats naturels.']),
 g:mix([bank([
  ['Pour chercher des informations sur les dinosaures du Jurassique, quels mots-clés choisir ?','dinosaures Jurassique',['je voudrais des informations sur les dinosaures s’il vous plaît','dinosaures','animaux préhistoriques peut-être'],'Des mots précis donnent de meilleurs résultats.'],
  ['À quoi servent les guillemets dans une recherche ?','à chercher une expression exacte',['à exclure un mot','à traduire la page','à changer de langue'],'Exemple : "cycle de l’eau".'],
  ['Dans une page de résultats, un lien marqué « Annonce » est…','une publicité payée pour apparaître en haut',['toujours le meilleur résultat','une source officielle obligatoirement','un lien gratuit sans lien commercial'],'Il ne s’agit pas d’un résultat naturel.'],
  ['Pourquoi comparer plusieurs résultats avant de conclure ?','pour vérifier que l’information est confirmée par plusieurs sources',['pour perdre du temps','ce n’est jamais utile','parce que le premier résultat est toujours faux'],'Une seule source peut se tromper.'],
  ['Le signe « - » devant un mot dans une recherche permet…','d’exclure ce mot des résultats',['de l’ajouter obligatoirement','de le traduire','de le mettre en gras'],'Exemple : jaguar -voiture.',2],
  ['Une recherche avec des mots-clés précis donne généralement…','des résultats plus pertinents',['toujours moins de résultats','toujours plus de publicités','des résultats au hasard'],'Les mots précis ciblent mieux le sujet.'],
  {tf:'Le premier résultat d’une recherche est toujours le plus fiable.',v:false,e:'L’ordre dépend d’algorithmes, pas de la fiabilité garantie.'},
  {tf:'Un moteur de recherche vérifie que toutes les pages qu’il indexe disent la vérité.',v:false,e:'Il indexe les pages contenant les mots cherchés, sans garantir leur véracité.',d:2},
  ['Taper une recherche sous forme de question complète plutôt que de mots-clés donne généralement…','des résultats moins précis',['toujours de meilleurs résultats','exactement les mêmes résultats','des résultats interdits'],'Les mots-clés ciblés sont plus efficaces.'],
  ['Chercher « climat Antarctique fonte glaciers » est plus efficace que…','« je voudrais savoir ce qui se passe avec le climat en Antarctique »',['« Antarctique »','« climat »','« glaciers Antarctique »'],'Des mots-clés précis, ni trop vagues ni trop longs, ciblent mieux le sujet.',2],
  ['Après une recherche, ouvrir plusieurs pages différentes plutôt qu’une seule permet…','de croiser les informations trouvées',['de perdre du temps pour rien','de rendre la recherche illégale','de changer de moteur de recherche automatiquement'],'Le croisement des sources renforce la fiabilité.'],
  ['Le résultat d’une recherche qui apparaît en tout premier est-il toujours écrit par un expert du sujet ?','pas nécessairement',['oui, systématiquement','oui, car le moteur vérifie les diplômes des auteurs','oui, seuls les experts apparaissent en premier'],'La position dans les résultats ne garantit pas la compétence de l’auteur.',2]]),2])},

{id:'emi6e',name:'Protéger son identité numérique',icon:'🪪',domain:'Citoyenneté numérique',
 refs:[REF_CLEMI+' — culture sociale et citoyenne',LOI2013,EDU],
 tip:'Avant de publier une information sur toi (photo, prénom, ville), demande-toi si tu accepterais qu’un inconnu la voie et la garde pour toujours.',
 c:C(`Ce que l’on publie en ligne (photos, messages, pseudonyme) forme une <b>identité numérique</b> : l’image que les autres se font de nous à partir de nos traces en ligne. La protéger, c’est réfléchir avant de publier et régler ses paramètres de confidentialité.`,
  [T('Identité numérique et traces',`<p>Chaque publication, commentaire ou recherche laisse une <b>trace</b>. Ces traces, accumulées, forment une <b>identité numérique</b>, visible par d’autres personnes (camarades, inconnus, parfois de futurs employeurs). Une trace publiée peut être copiée et rester visible longtemps, même après suppression.</p>`),
   T('Se protéger',`<p>On règle ses comptes en mode <b>privé</b> quand c’est possible, on réfléchit avant de publier une information personnelle (adresse, numéro, localisation), et on ne publie pas d’informations sur les autres sans leur accord. On vérifie régulièrement ce qui est visible sur son propre profil.</p>`)],
  [{q:'Un élève veut publier une photo de sa maison avec l’adresse visible sur la boîte aux lettres. Que lui conseiller ?',s:['L’adresse est une information personnelle sensible.','La photo peut être copiée et rester en ligne longtemps.','Mieux vaut flouter ou éviter de montrer l’adresse.']}],
  ['Je réfléchis avant de publier une information personnelle.','Je sais qu’une publication peut être copiée.','Je règle mes comptes en mode privé si possible.','Je ne publie pas d’information sur les autres sans leur accord.'],
  ['Croire qu’une publication supprimée disparaît partout.','Publier l’adresse ou le numéro de quelqu’un.','Accepter tous les paramètres par défaut sans les vérifier.'],
  ['Identité numérique = traces accumulées.','Une trace peut être copiée durablement.','Confidentialité et accord des autres.']),
 g:mix([sort({'Information sensible à ne pas publier publiquement':['son adresse postale complète','son numéro de téléphone','sa localisation en temps réel'],'Information qu’on peut généralement partager':['le titre d’un exposé fait en classe','le résultat d’un match de sport collectif connu de tous','une recette de cuisine']},{q:'« %s » est…'}),2],
  [bank([
   ['L’identité numérique, c’est…','l’image qu’on donne de soi à travers ses traces en ligne',['un mot de passe','un logiciel antivirus','une carte d’identité scannée'],'Elle se construit avec toutes les publications.'],
   ['Une publication supprimée peut-elle rester visible malgré tout ?','oui, si elle a été copiée (capture d’écran, partage)',['non, jamais','non, c’est impossible techniquement','oui, mais seulement pendant une heure'],'Une copie échappe à la suppression originale.'],
   ['Publier la photo d’un camarade sans son accord est…','une atteinte à son droit à l’image',['toujours autorisé entre amis','sans aucune conséquence','une obligation entre camarades'],'L’accord de la personne concernée est nécessaire.'],
   ['Régler un compte en mode « privé » signifie…','que seules les personnes autorisées voient les publications',['que le compte est supprimé','que tout le monde voit tout','que le compte n’existe plus'],'Cela limite qui voit le contenu.'],
   {tf:'Toutes les informations qu’on publie sur soi restent sous notre contrôle total pour toujours.',v:false,e:'Une fois publiée, une information peut être copiée et échapper à ce contrôle.'},
   {tf:'Vérifier régulièrement ce qui est visible sur son profil est une bonne pratique.',v:true,e:'Cela permet de corriger ce qui ne devrait pas être visible.'}]),2])},

{id:'emi6f',name:'Produire et partager une information responsable',icon:'✍️',domain:'Publication',
 refs:[REF_CLEMI+' — culture informationnelle et sociale et citoyenne',CPI,EDU],
 tip:'Avant de partager : est-ce vrai (vérifié) ? est-ce que j’ai le droit (sources, images) ? est-ce que je dirais la même chose en face de quelqu’un ?',
 c:C(`Publier une information — un article de classe, une légende de photo, un message dans un groupe — engage une <b>responsabilité</b> : il faut vérifier ce qu’on écrit, citer ses sources et respecter les droits des auteurs et des personnes concernées.`,
  [T('Vérifier avant de publier',`<p>Avant de partager une information, on se demande : est-elle <b>vérifiée</b> (voir le chapitre « Identifier une source ») ? Est-ce un <b>fait</b> ou une <b>opinion</b> présentée comme un fait ? A-t-on vérifié auprès d’au moins deux sources fiables ?</p>`),
   T('Citer et respecter les droits',`<p>Un texte, une image ou une musique appartiennent à leur auteur (<b>droit d’auteur</b>) : on cite la source d’une information ou d’une image qu’on réutilise. On ne publie pas la photo de quelqu’un sans son accord. Un ton <b>respectueux</b> évite les polémiques inutiles.</p>`)],
  [{q:'Pour le journal du collège, un élève veut publier un article sur un fait non confirmé qu’il a entendu dire.',s:['Il doit vérifier l’information auprès d’au moins une source fiable avant de la publier.','S’il utilise une image trouvée en ligne, il doit en citer la source.','Il doit rester factuel et respectueux dans ses propos.']}],
  ['Je vérifie l’information avant de la publier.','Je cite mes sources (texte, images).','Je respecte le droit d’auteur et le droit à l’image.','Je reste factuel et respectueux dans ce que j’écris.'],
  ['Publier une rumeur non vérifiée.','Utiliser une image sans en citer la source.','Publier des propos irrespectueux envers quelqu’un.'],
  ['Vérifier avant de publier.','Citer ses sources (droit d’auteur).','Respect et exactitude.']),
 g:mix([bank([
  ['Avant de publier une information, il faut d’abord…','la vérifier auprès d’une source fiable',['la partager immédiatement','l’embellir pour qu’elle soit plus intéressante','ne rien vérifier, ce n’est pas nécessaire'],'La vérification évite de diffuser une erreur.'],
  ['Utiliser une image trouvée en ligne sans en citer la source est…','une atteinte au droit d’auteur',['toujours autorisé','sans conséquence','une pratique recommandée'],'Les images appartiennent à leurs auteurs.'],
  ['Publier la photo de quelqu’un sans son accord est…','une atteinte au droit à l’image',['sans problème si la photo est jolie','toujours autorisé pour un journal scolaire','obligatoire pour informer'],'L’accord préalable est nécessaire.'],
  ['Pourquoi rester factuel plutôt que d’enjoliver une information ?','pour ne pas déformer la vérité',['pour rendre l’article plus intéressant','ce n’est pas important','pour attirer plus de lecteurs à tout prix'],'La déformation nuit à la fiabilité de l’information.'],
  ['Citer ses sources dans un article permet…','de montrer d’où vient l’information et de la rendre vérifiable',['de rallonger artificiellement le texte','de cacher ses propres idées','ce n’est jamais utile'],'Cela renforce la crédibilité de l’article.'],
  {tf:'Un article pour le journal du collège doit être vérifié avant publication, comme dans un vrai média.',v:true,e:'La rigueur s’applique aussi aux productions scolaires.'},
  {tf:'On peut publier n’importe quelle rumeur tant qu’elle est présentée comme « on dit que… ».',v:false,e:'Présenter une rumeur comme telle ne dispense pas de la vérifier avant de la diffuser largement.',d:2},
  ['Avant de publier une légende sous une photo, il est utile de vérifier…','qu’elle décrit correctement ce que montre la photo',['qu’elle est la plus longue possible','qu’elle contient le plus de mots possible','rien, une légende n’a pas d’importance'],'Une légende inexacte peut induire en erreur.'],
  ['Relire un article avant de le publier permet de…','corriger les erreurs et vérifier le ton employé',['le rendre plus long artificiellement','gagner du temps en l’envoyant plus vite','éviter de citer ses sources'],'La relecture fait partie d’une publication responsable.'],
  ['Si on n’est pas sûr qu’une information soit vraie, le plus responsable est de…','ne pas la publier tant qu’elle n’est pas vérifiée',['la publier en espérant que c’est vrai','la publier avec un point d’interrogation sans vérifier davantage','la publier car elle est intéressante'],'Le doute justifie d’attendre une vérification.'],
  ['Publier une information fausse par erreur, puis la corriger rapidement en le signalant, est…','une bonne pratique quand une erreur est découverte',['une faute qui ne doit jamais être reconnue','interdit de corriger une publication déjà faite','sans aucune importance'],'Reconnaître et corriger une erreur est responsable.'],
  ['Pour une information sensible, attendre d’avoir deux sources fiables avant de publier est…','une précaution raisonnable',['une perte de temps inutile','interdit par la loi','une marque de manque de sérieux'],'Le recoupement des sources limite le risque d’erreur.']]),2])}
]);

MQ.add('emi','5',[
{id:'emi5a',name:'Vérifier une information et croiser les sources',icon:'🧐',domain:'Esprit critique',
 refs:[REF_CLEMI+' — culture informationnelle',EDU],
 tip:'Une information confirmée par deux ou trois sources indépendantes et sérieuses est plus solide qu’une information isolée, même si elle vient d’un site qui semble sérieux.',
 c:C(`En 5e, on va plus loin que repérer une source : on apprend à <b>vérifier</b> méthodiquement une information, en la <b>croisant</b> avec d’autres sources indépendantes avant de la croire ou de la partager.`,
  [T('La méthode de vérification',`<p>Pour vérifier une information : identifier l’<b>auteur</b> et sa compétence sur le sujet, vérifier la <b>date</b>, chercher si d’autres médias <b>indépendants</b> (n’appartenant pas au même groupe, n’ayant pas repris simplement l’un de l’autre) rapportent la même information, et comparer les éventuelles différences.</p>`),
   T('Sources indépendantes',`<p>Deux sources sont <b>indépendantes</b> si elles n’ont pas simplement copié l’une sur l’autre. Si cinq sites reprennent tous le même article sans enquête propre, cela ne fait pas « cinq preuves » : c’est une seule source répétée. On cherche plutôt des sources qui ont fait leur propre vérification.</p>`)],
  [{q:'Une information circule : « Un nouveau virus serait apparu dans une ville voisine. » Cinq comptes la partagent, tous en recopiant le même texte.',s:['Ces cinq partages ne sont pas cinq sources indépendantes : c’est le même texte recopié.','Il faut chercher si un média d’information sérieux, avec sa propre enquête, en parle.','Sans confirmation indépendante, ne pas partager l’information.']}],
  ['Je vérifie l’auteur et la date d’une information.','Je cherche des sources réellement indépendantes.','Je comprends que des partages multiples du même texte ne sont pas plusieurs preuves.','Je m’abstiens de partager une information non confirmée.'],
  ['Confondre un texte recopié plusieurs fois avec plusieurs preuves.','Croire une information uniquement parce qu’un site semble sérieux visuellement.','Ignorer la date d’une information (parfois ancienne, présentée comme récente).'],
  ['Vérifier auteur, date, indépendance des sources.','Sources indépendantes ≠ copies multiples.','Recouper avant de croire ou partager.']),
 g:mix([bank([
  ['Deux sources sont dites « indépendantes » si…','elles n’ont pas simplement copié l’une sur l’autre',['elles sont publiées le même jour','elles ont le même nombre de lecteurs','elles utilisent la même couleur de site'],'Chacune doit avoir fait sa propre vérification.'],
  ['Cinq comptes qui recopient le même texte constituent…','une seule source répétée, pas cinq preuves',['cinq preuves solides','une information automatiquement vraie','une enquête complète'],'La répétition n’est pas une vérification.'],
  ['Pourquoi vérifier la date d’une information ?','une ancienne information peut être présentée à tort comme récente',['la date n’a aucune importance','pour savoir combien de personnes l’ont lue','pour connaître le jour de la semaine'],'Une photo ou un fait ancien peut tromper s’il est mal daté.'],
  ['Pour vérifier une information inquiétante qui circule, le plus fiable est de…','chercher si un média d’information reconnu, avec sa propre enquête, la confirme',['la partager à beaucoup de personnes pour « prévenir »','y croire si elle fait peur','ignorer complètement la question'],'Un média sérieux a ses propres méthodes de vérification.'],
  ['Si on ne trouve aucune confirmation indépendante d’une rumeur, il vaut mieux…','ne pas la partager',['la partager quand même « au cas où »','la modifier avant de la partager','la partager uniquement à ses amis proches'],'Le doute justifie la prudence.'],
  {tf:'Un fait vérifié par plusieurs sources réellement indépendantes est plus solide qu’une affirmation isolée.',v:true,e:'Le recoupement renforce la fiabilité.'},
  {tf:'Si un site a un design soigné et professionnel, l’information qu’il publie est automatiquement vraie.',v:false,e:'L’apparence ne garantit pas le contenu : il faut vérifier la source.',d:2},
  ['Comparer les différences entre plusieurs sources sur un même sujet permet…','de repérer ce qui est confirmé et ce qui reste incertain',['de perdre du temps inutilement','de choisir la source la plus courte','de deviner laquelle est payante'],'Les écarts entre sources donnent des indices utiles.',2],
  ['Un expert reconnu du sujet qui s’exprime dans son domaine de compétence est…','une source généralement plus fiable qu’un avis anonyme',['toujours automatiquement infaillible','une source sans aucune valeur','identique à n’importe quel avis non spécialisé'],'La compétence sur le sujet renforce la crédibilité, sans garantir une vérité absolue.'],
  ['Deux médias appartenant au même groupe et reprenant la même dépêche sans enquête propre constituent-ils deux sources indépendantes ?','non',['oui, car ce sont deux médias différents','oui, car ils ont des noms différents','oui, toujours'],'L’indépendance suppose une vérification propre à chacun.',2],
  ['Une agence de presse qui fournit la même dépêche à plusieurs journaux est…','une source commune, pas une multiplication de sources indépendantes',['toujours une source peu fiable','une preuve que l’information est fausse','une source différente pour chaque journal qui la publie'],'Les journaux abonnés reprennent souvent la même dépêche.',2],
  ['Trouver une information confirmée uniquement sur des sites qui se citent entre eux en boucle, sans source extérieure, doit…','rendre prudent, car cela peut être un cercle fermé sans vérification réelle',['renforcer totalement la confiance','suffire à considérer l’information comme certaine','ne poser aucune question particulière'],'Un cercle de citations mutuelles ne remplace pas une vérification indépendante.',3]]),2])},

{id:'emi5b',name:'Comprendre titre, angle et hiérarchie de l’information',icon:'🗞️',domain:'Médias',
 refs:[REF_CLEMI+' — culture médiatique',EDU],
 tip:'Un titre « choc » n’est pas forcément faux, mais il peut exagérer ce que montre réellement l’article : il faut toujours lire le contenu, pas seulement le titre.',
 c:C(`Un même événement peut être présenté très différemment selon le <b>titre</b> choisi, l’<b>angle</b> adopté par le journaliste, et la place accordée à l’information (sa <b>hiérarchie</b>) dans un journal ou un site.`,
  [T('Le titre et l’angle',`<p>Le <b>titre</b> résume l’article pour attirer l’attention ; il peut parfois exagérer ou simplifier. L’<b>angle</b> est le point de vue choisi pour traiter un sujet : un même événement (une grève, par exemple) peut être présenté du point de vue des usagers, des salariés, ou de l’entreprise.</p>`),
   T('La hiérarchie de l’information',`<p>La <b>hiérarchie de l’information</b> désigne la place et la taille accordées à chaque sujet (en première page, en gros titre, ou en petit article en fin de journal). Cette hiérarchie reflète les choix d’un média : elle n’est jamais totalement neutre, même si elle suit en général des critères comme l’importance ou l’actualité du sujet.</p>`)],
  [{q:'Deux journaux titrent différemment sur la même grève : « Grève : les usagers pénalisés » et « Grève : les salariés réclament leurs droits ».',s:['Les deux titres parlent du même événement.','Ils adoptent des angles différents (du point de vue des usagers ou des salariés).','Lire plusieurs angles donne une vision plus complète du sujet.']}],
  ['Je repère qu’un titre peut exagérer ou simplifier.','Je distingue plusieurs angles possibles sur un même sujet.','Je comprends ce qu’est la hiérarchie de l’information.','Je lis le contenu complet, pas seulement le titre.'],
  ['Se contenter de lire un titre sans ouvrir l’article.','Croire qu’un seul angle donne toute la vérité.','Penser que la place d’un article est toujours neutre.'],
  ['Titre : résumé, parfois exagéré.','Angle : point de vue choisi.','Hiérarchie : place accordée à l’information.']),
 g:mix([sort({'Angle « usagers »':['les voyageurs attendent des heures à la gare','les clients ne peuvent plus utiliser le service habituel'],'Angle « salariés »':['les employés réclament une revalorisation de salaire','le personnel dénonce ses conditions de travail']},{q:'« %s » correspond à un angle…'}),2],
  [bank([
   ['Le titre d’un article sert à…','résumer et attirer l’attention sur le contenu',['remplacer la lecture de l’article','donner toujours des informations fausses','être ignoré systématiquement'],'Il peut parfois simplifier ou exagérer.'],
   ['L’angle d’un article désigne…','le point de vue choisi pour traiter le sujet',['la taille des lettres du titre','le nombre de photos','la couleur du papier'],'Différents angles peuvent coexister sur un même sujet.'],
   ['La hiérarchie de l’information correspond à…','la place et l’importance accordées à chaque sujet',['le prix du journal','le nombre de pages total','la date de publication uniquement'],'Un sujet peut être en première page ou en dernière.'],
   ['Lire uniquement le titre d’un article permet-il de comprendre tout son contenu ?','non, le titre ne donne qu’un résumé partiel',['oui, toujours','oui, car le titre dit toujours tout','oui, dans la majorité des cas'],'Le contenu complet apporte des nuances.'],
   ['Un même événement traité sous deux angles différents est-il forcément contradictoire ?','non, les deux angles peuvent être complémentaires',['oui, toujours','oui, un seul peut être vrai','oui, cela signifie que l’un des deux journaux a menti'],'Plusieurs points de vue légitimes peuvent coexister.',2],
   {tf:'La place accordée à un sujet dans un média reflète des choix, jamais totalement neutres.',v:true,e:'Même selon des critères objectifs, un choix éditorial intervient.',d:2},
   {tf:'Un titre « choc » signifie toujours que l’article contient une information fausse.',v:false,e:'Un titre accrocheur peut rester fidèle au contenu, même s’il simplifie.'},
  ['Un article relégué en dernière page d’un journal est-il nécessairement sans importance ?','pas nécessairement, la hiérarchie reflète des choix, pas toujours l’importance réelle',['oui, toujours sans aucune importance','oui, car la dernière page n’est jamais lue','oui, par définition'],'La place choisie dépend aussi de la ligne éditoriale.',2]]),2])},

{id:'emi5c',name:'Image, cadrage et manipulation',icon:'📷',domain:'Image',
 refs:[REF_CLEMI+' — culture médiatique et technique',EDU],
 tip:'Une photo authentique peut tout de même tromper si elle est recadrée, sortie de son contexte ou mal légendée : regarde toujours ce qui a été coupé, et cherche son origine et sa date.',
 c:C(`Une image — photo ou vidéo — semble souvent « parler d’elle-même », mais elle peut être <b>cadrée</b>, <b>recadrée</b>, <b>sortie de son contexte</b> ou <b>légendée</b> de façon trompeuse, sans même être truquée.`,
  [T('Le cadrage',`<p>Le <b>cadrage</b> est le choix de ce que l’on montre et de ce que l’on exclut de l’image. Une photo cadrée pour montrer une foule dense peut paraître très différente si l’on voit, hors cadre, que la rue est en réalité peu fréquentée. Rien n’est faux dans l’image, mais elle donne une impression partielle.</p>`),
   T('Contexte et légende',`<p>Une photo authentique peut être présentée avec une <b>légende</b> fausse (mauvais lieu, mauvaise date, mauvais événement) : c’est la sortir de son <b>contexte</b>. La <b>recherche d’image inversée</b> (chercher où une image a déjà été publiée) permet souvent de retrouver son origine réelle et sa date véritable.</p>`)],
  [{q:'Une photo de foule immense circule avec la légende « Manifestation d’hier dans notre ville ». Comment la vérifier ?',s:['Faire une recherche d’image inversée pour retrouver son origine.','La photo existe en ligne depuis plusieurs années, prise dans une autre ville.','Conclusion : la légende est trompeuse, l’image est sortie de son contexte.']}],
  ['Je comprends qu’un cadrage peut donner une impression partielle.','Je me méfie d’une légende qui pourrait être fausse.','J’utilise la recherche d’image inversée pour vérifier une origine.','Je distingue une image truquée d’une image mal contextualisée.'],
  ['Croire qu’une photo authentique ne peut jamais tromper.','Ignorer qu’une image peut être recadrée pour changer son sens.','Ne jamais vérifier l’origine d’une photo surprenante.'],
  ['Cadrage : ce qui est montré ou exclu.','Légende fausse = sortie de contexte.','Recherche d’image inversée.']),
 g:mix([bank([
  ['Le cadrage d’une photo désigne…','le choix de ce qui est montré et de ce qui est exclu de l’image',['la résolution de l’image en pixels','la couleur dominante','le format du fichier'],'Il influence l’impression donnée, sans forcément être trompeur en soi.'],
  ['Une photo authentique mais présentée avec une mauvaise légende est-elle trompeuse ?','oui, car elle est sortie de son contexte',['non, une photo vraie ne peut jamais tromper','non, la légende n’a aucune importance','non, seules les photos truquées trompent'],'Le contexte compte autant que l’image elle-même.'],
  ['La recherche d’image inversée permet de…','retrouver l’origine et la date réelle d’une image',['modifier la couleur d’une image','créer une nouvelle image','supprimer une image d’Internet'],'Un outil utile pour vérifier le contexte d’une photo.'],
  ['Une photo cadrée pour exclure un détail important donne…','une impression potentiellement partielle, même sans être truquée',['toujours une impression totalement fausse','toujours une impression parfaitement complète','aucune impression particulière'],'Le cadrage sélectionne ce qu’on voit.'],
  ['Une image peut-elle être authentique et quand même tromper ?','oui, si son contexte ou sa légende est faux',['non, une image authentique dit toujours toute la vérité','non, c’est impossible','non, seule une image truquée peut tromper'],'Le contexte et la légende comptent beaucoup.',2],
  {tf:'Une vieille photo peut être présentée à tort comme récente.',v:true,e:'La vérification de la date est essentielle.'},
  {tf:'Si une photo n’a pas été modifiée numériquement, elle ne peut jamais induire en erreur.',v:false,e:'Le cadrage et la légende peuvent tromper sans aucune modification de l’image.',d:2},
  ['Zoomer sur une petite partie d’une photo pour en faire une nouvelle image s’appelle…','un recadrage',['un filtre colorimétrique','une compression','un format vectoriel'],'Il modifie ce qui est montré sans changer le contenu de la zone conservée.'],
  ['Pourquoi vérifier systématiquement d’où provient une image surprenante avant de la croire ?','parce qu’elle peut être ancienne, recadrée ou mal légendée',['parce que toute image est obligatoirement truquée','ce n’est jamais utile','parce que les images ne peuvent pas se vérifier'],'Plusieurs manipulations simples existent sans trucage numérique.'],
  ['Une image accompagnée d’un lieu et d’une date erronés reste-t-elle fiable comme preuve de cet événement précis ?','non',['oui, car l’image elle-même n’a pas été modifiée','oui, toujours','oui, si elle est nette'],'La légende fait partie de l’information transmise par l’image.',2],
  ['Observer les ombres, les reflets ou les détails d’arrière-plan d’une photo peut aider à…','repérer des incohérences ou confirmer son contexte',['ne jamais rien apprendre d’une image','rendre l’image automatiquement fausse','changer la définition de l’image'],'Ces détails donnent parfois des indices sur le lieu ou le moment.',2],
  ['Une image partagée sans aucune indication de lieu, de date ni d’auteur doit être traitée avec…','prudence, car son contexte réel n’est pas connu',['une confiance totale et immédiate','un rejet systématique sans aucune vérification possible','indifférence, cela n’a pas d’importance'],'L’absence d’informations invite à chercher une vérification avant de la diffuser.']]),2])},

{id:'emi5d',name:'Réseaux sociaux et économie de l’attention',icon:'📲',domain:'Réseaux sociaux',
 refs:[REF_CLEMI+' — culture sociale et citoyenne et technique',EDU],
 tip:'Un contenu qui provoque une émotion forte (colère, peur, indignation) est souvent conçu pour capter ton attention plus longtemps : un réflexe utile est de prendre un peu de recul avant de réagir ou de partager.',
 c:C(`Les réseaux sociaux ne se contentent pas d’afficher du contenu : ils sont conçus pour capter et garder notre <b>attention</b> le plus longtemps possible. Comprendre ce mécanisme, parfois appelé <b>économie de l’attention</b>, aide à garder un regard critique.`,
  [T('Capter l’attention',`<p>Les plateformes gagnent de l’argent, notamment grâce à la <b>publicité</b>, proportionnellement au <b>temps passé</b> par les utilisateurs. Elles utilisent des techniques comme les <b>notifications</b>, le <b>défilement infini</b> (scroll) ou la mise en avant de contenus qui suscitent de fortes émotions, car ces contenus retiennent davantage l’attention.</p>`),
   T('Garder un regard critique',`<p>Un contenu qui provoque une <b>émotion forte</b> (colère, indignation, peur) circule souvent plus vite, qu’il soit vrai ou non. Prendre le temps de <b>vérifier</b> avant de réagir, limiter son <b>temps d’écran</b>, et désactiver certaines notifications sont des réflexes utiles pour ne pas se laisser entraîner.</p>`)],
  [{q:'Une vidéo très partagée provoque une forte indignation chez de nombreux internautes. Que faire avant de réagir ?',s:['Se demander si le contenu est vérifié ou sorti de son contexte.','Les contenus qui provoquent une émotion forte circulent souvent plus vite.','Prendre le temps de vérifier avant de partager ou de commenter.']}],
  ['Je comprends que les plateformes cherchent à capter mon attention.','Je repère les techniques qui favorisent un temps d’écran plus long.','Je me méfie des contenus qui suscitent une forte émotion.','Je prends le temps de vérifier avant de réagir ou de partager.'],
  ['Croire qu’un contenu qui provoque une émotion forte est forcément vrai.','Partager immédiatement sans vérifier, « sous le coup de l’émotion ».','Ignorer que le temps passé a une valeur économique pour la plateforme.'],
  ['Économie de l’attention.','Notifications, défilement infini, émotions fortes.','Prendre du recul avant de réagir.']),
 g:mix([bank([
  ['Pourquoi les plateformes de réseaux sociaux cherchent-elles à capter notre attention le plus longtemps possible ?','parce qu’elles gagnent de l’argent, notamment via la publicité, proportionnellement au temps passé',['parce que c’est obligatoire par la loi','parce que cela n’a aucun intérêt économique','par pure générosité'],'Plus on reste, plus la plateforme peut afficher de publicités.'],
  ['Un contenu qui provoque une forte émotion (colère, peur) circule-t-il en général plus vite qu’un contenu neutre ?','oui, en général',['non, jamais','non, toujours moins vite','cela ne dépend d’aucun facteur'],'Les émotions fortes favorisent le partage rapide.'],
  ['Le défilement infini (scroll) est une technique qui…','encourage à continuer à regarder du contenu sans interruption naturelle',['empêche totalement de quitter l’application','n’a aucun effet sur le temps passé','sert uniquement à économiser de la batterie'],'Il n’y a pas de « fin de page » qui inciterait à arrêter.'],
  ['Avant de partager un contenu qui suscite une forte indignation, il est utile de…','prendre le temps de vérifier s’il est exact ou sorti de son contexte',['le partager immédiatement pour prévenir les autres','l’ignorer complètement sans réfléchir','le modifier avant de le partager'],'La réaction à chaud peut amplifier une désinformation.'],
  ['Les notifications répétées d’une application cherchent notamment à…','inciter à rouvrir l’application régulièrement',['informer uniquement de choses très importantes','économiser la batterie du téléphone','protéger la vie privée de l’utilisateur'],'Elles rappellent la présence de l’application.'],
  {tf:'Limiter certaines notifications peut aider à reprendre le contrôle de son temps d’écran.',v:true,e:'C’est un réflexe recommandé.'},
  {tf:'Le temps passé par les utilisateurs sur une plateforme n’a aucune valeur économique pour elle.',v:false,e:'Il en a, notamment via la publicité.',d:2},
  ['Une vidéo recommandée automatiquement après celle qu’on regarde résulte…','d’un algorithme de recommandation conçu pour prolonger le temps passé',['du hasard total','d’un choix fait uniquement par d’autres utilisateurs','d’une obligation légale'],'Les plateformes cherchent à maintenir l’attention.'],
  ['Prendre une pause volontaire après un long moment passé sur une application est…','une bonne habitude pour garder le contrôle de son temps',['inutile','interdit par les plateformes','sans aucun effet sur l’usage'],'Cela permet de reprendre du recul.'],
  ['Pourquoi les contenus les plus partagés ne sont-ils pas toujours les plus fiables ?','parce que l’émotion qu’ils provoquent favorise le partage, pas forcément leur exactitude',['parce que le partage garantit toujours leur fiabilité','parce que les contenus fiables ne se partagent jamais','parce que cela n’a aucun lien'],'La viralité et la véracité sont deux choses différentes.',2],
  ['Un compte à rebours ou une mention « Plus que 2 exemplaires ! » sur une application cherche surtout à…','provoquer une décision rapide, sans laisser le temps de réfléchir',['informer de façon totalement neutre','protéger les données personnelles','ralentir volontairement l’utilisateur'],'C’est une technique qui joue sur l’urgence ressentie.',2],
  ['Désactiver certaines notifications non essentielles permet…','de réduire les interruptions et de reprendre le contrôle de son attention',['de supprimer définitivement l’application','d’empêcher toute utilisation future de l’application','de rendre l’application payante'],'On choisit ce qui mérite réellement une alerte immédiate.']]),2])},

{id:'emi5e',name:'Droit d’auteur et réutilisation',icon:'©️',domain:'Droit',
 refs:[REF_CLEMI+' — culture sociale et citoyenne',CPI,EDU],
 tip:'Avant de réutiliser une image, un texte ou une musique trouvés en ligne : vérifie sa licence, respecte ses conditions et crédite l’auteur.',
 c:C(`Les textes, images, musiques et vidéos trouvés en ligne ont, presque toujours, un <b>auteur</b> et sont protégés par le <b>droit d’auteur</b>. Les réutiliser pour un exposé, une vidéo ou une publication demande de connaître quelques règles simples.`,
  [T('Le principe du droit d’auteur',`<p>Dès sa création, une œuvre (texte, image, musique, vidéo) appartient à son <b>auteur</b>, qui décide des conditions de sa réutilisation. Trouver une œuvre « librement » sur Internet ne signifie pas qu’elle est libre de droits : il faut vérifier sa <b>licence</b>.</p>`),
   T('Licences et attribution',`<p>Les licences <b>Creative Commons</b> précisent les conditions de réutilisation : <b>BY</b> (citer l’auteur), <b>NC</b> (pas d’usage commercial), <b>ND</b> (pas de modification), <b>SA</b> (partage dans les mêmes conditions). Même quand la réutilisation est permise, on <b>crédite</b> l’auteur et on cite la licence utilisée.</p>`)],
  [{q:'Pour illustrer un exposé, un élève trouve une photo sous licence Creative Commons CC BY.',s:['Il peut l’utiliser, y compris en la modifiant, selon les conditions de cette licence.','La condition BY impose de citer l’auteur de la photo.','Il ajoute une légende avec le nom de l’auteur et la mention de la licence.']}],
  ['Je sais qu’une œuvre trouvée en ligne a presque toujours un auteur.','Je vérifie la licence avant de réutiliser un contenu.','Je connais le sens de BY, NC, ND et SA.','Je crédite l’auteur même quand la réutilisation est autorisée.'],
  ['Croire qu’une image trouvée en ligne est automatiquement libre de droits.','Réutiliser une image sous licence ND en la modifiant.','Oublier de citer l’auteur d’une œuvre réutilisée.'],
  ['Droit d’auteur dès la création.','Licences Creative Commons : BY, NC, ND, SA.','Toujours créditer l’auteur.']),
 g:mix([pairs([['BY','citer l’auteur'],['NC','pas d’utilisation commerciale'],['ND','pas de modification de l’œuvre'],['SA','partager l’œuvre modifiée sous la même licence']],{q:'Dans une licence Creative Commons, la mention « %s » signifie…',rq:'Quelle mention Creative Commons signifie : %s ?'}),2],
  [bank([
   ['Une œuvre trouvée librement en ligne (sans payer) est-elle automatiquement libre de droits ?','non, il faut vérifier sa licence',['oui, toujours','oui, si elle est jolie','oui, si elle a plus de dix ans'],'« Accessible » ne veut pas dire « libre de droits ».'],
   ['Une photo sous licence CC BY-ND peut-elle être modifiée puis publiée ?','non, car ND interdit la modification',['oui, sans aucune condition','oui, si on ne cite pas l’auteur','oui, uniquement pour un usage commercial'],'ND = pas de modification de l’œuvre.',2],
   ['Que signifie créditer un auteur ?','indiquer son nom et la source de l’œuvre utilisée',['lui payer une somme d’argent obligatoirement','lui demander une autorisation par écrit dans tous les cas','le citer uniquement s’il est célèbre'],'C’est une marque de respect et souvent une obligation légale.'],
   ['Le droit d’auteur protège une œuvre…','dès sa création, sans formalité particulière',['uniquement si elle est déposée dans un registre officiel','uniquement si l’auteur est connu du public','uniquement pour les œuvres payantes'],'Aucune démarche n’est nécessaire pour être protégé.',2],
   {tf:'La licence Creative Commons CC0 signifie que l’auteur renonce à ses droits autant que la loi le permet.',v:true,e:'C’est la licence la plus permissive.'},
   {tf:'Toute image disponible sans mot de passe sur Internet peut être utilisée librement sans condition.',v:false,e:'Elle reste protégée par le droit d’auteur, sauf indication contraire.'}]),2])},

{id:'emi5f',name:'Réaliser une production médiatique',icon:'🎬',domain:'Publication',
 refs:[REF_CLEMI+' — culture médiatique et technique',EDU],
 tip:'Avant de publier une production médiatique (article, podcast, vidéo) : relire, vérifier les informations, citer les sources et les images utilisées.',
 c:C(`Réaliser une <b>production médiatique</b> (article pour le journal du collège, podcast, courte vidéo) permet de mettre en pratique ce que l’on a appris sur l’information : choisir un sujet, l’organiser, et respecter les règles de vérification et de citation.`,
  [T('Organiser une production',`<p>Choisir un <b>sujet</b> précis, définir un <b>angle</b>, rassembler des informations vérifiées, rédiger un <b>plan</b> avant d’écrire ou d’enregistrer. Pour une interview, préparer des questions ouvertes (voir le travail sur les questions en orientation). Un titre clair résume le contenu sans l’exagérer.</p>`),
   T('Avant la publication',`<p>Relire ou réécouter la production, vérifier les faits avancés, citer les <b>sources</b> utilisées (textes, images, témoignages), et s’assurer d’avoir le droit d’utiliser chaque image ou extrait. Un ton <b>respectueux</b> évite les polémiques inutiles.</p>`)],
  [{q:'Un groupe d’élèves prépare un podcast sur le réchauffement climatique local.',s:['Choisir un angle précis : par exemple l’impact sur l’agriculture locale.','Vérifier les chiffres utilisés auprès de sources fiables.','Citer les sources et relire le script avant d’enregistrer.']}],
  ['Je choisis un sujet et un angle précis.','Je prépare un plan avant de produire.','Je vérifie les informations et je cite mes sources.','Je m’assure d’avoir le droit d’utiliser chaque image ou extrait.'],
  ['Improviser sans préparation ni vérification.','Oublier de citer une source ou une image utilisée.','Choisir un ton irrespectueux pour « faire sensation ».'],
  ['Sujet, angle, plan.','Vérification et citation des sources.','Ton respectueux, droits respectés.']),
 g:mix([bank([
  ['Avant de produire un contenu médiatique, il est utile de définir…','un sujet précis et un angle',['uniquement un titre accrocheur','rien, on improvise directement','uniquement la durée du contenu'],'Cela structure le travail de production.'],
  ['Pour une interview, préparer des questions ouvertes permet…','d’obtenir des réponses développées et intéressantes',['d’obtenir uniquement des réponses oui/non','de perdre du temps','de décourager la personne interrogée'],'Les questions ouvertes enrichissent l’échange.'],
  ['Avant de publier une production, il faut…','vérifier les informations et citer les sources utilisées',['publier le plus vite possible sans relecture','ignorer les droits sur les images utilisées','exagérer pour attirer l’attention'],'La rigueur s’applique aussi aux productions scolaires.'],
  ['Utiliser un extrait vidéo trouvé en ligne dans sa propre production nécessite…','de vérifier qu’on a le droit de le réutiliser',['aucune vérification particulière','de le modifier pour le rendre méconnaissable','rien, les vidéos en ligne sont toutes libres'],'Le droit d’auteur s’applique aussi aux vidéos.'],
  ['Un titre clair pour une production médiatique doit…','résumer le contenu sans l’exagérer',['toujours être le plus choquant possible','ne jamais correspondre au contenu réel','être le plus long possible'],'Un bon titre informe honnêtement.'],
  {tf:'Une production réalisée par des élèves n’a pas besoin d’être vérifiée comme un vrai média.',v:false,e:'La rigueur et le respect des règles s’appliquent aussi aux productions scolaires.'},
  {tf:'Choisir un ton respectueux dans une production médiatique évite des polémiques inutiles.',v:true,e:'Le respect reste une règle de base, même en traitant un sujet sensible.'},
  ['Faire relire son script ou son article par une autre personne avant publication permet…','de repérer des erreurs ou un ton inadapté qu’on n’avait pas vus soi-même',['de perdre du temps pour rien','de ne jamais publier','d’affaiblir obligatoirement le contenu'],'Un regard extérieur apporte souvent des corrections utiles.'],
  ['Si un témoignage recueilli pour une production contient une information invérifiable, il vaut mieux…','le signaler comme tel ou chercher à le confirmer autrement',['le publier tel quel en le présentant comme un fait certain','le supprimer entièrement de la production sans aucune mention','l’exagérer pour qu’il semble plus crédible'],'La transparence sur l’incertitude reste honnête.'],
  ['Pour un podcast ou une vidéo, préparer un script ou un plan avant d’enregistrer permet…','de structurer les propos et d’éviter les oublis importants',['de rendre la production plus longue sans raison','d’empêcher toute spontanéité utile','de se dispenser de vérifier les informations'],'La préparation améliore la clarté sans empêcher la spontanéité.'],
  ['Inclure dans sa production une mention des limites de l’enquête (par exemple « un seul témoignage disponible ») est…','une marque d’honnêteté envers le public',['une faiblesse à toujours cacher','interdit dans une production scolaire','sans aucune utilité'],'Signaler les limites d’une enquête renforce sa crédibilité plutôt que de l’affaiblir.'],
  ['Demander l’accord d’une personne avant de publier son témoignage filmé ou enregistré est…','nécessaire, même pour une production scolaire',['inutile si la production reste au collège','nécessaire uniquement pour les adultes','jamais obligatoire'],'Le droit à l’image et à la parole s’applique aussi aux productions d’élèves.']]),2])}
]);

MQ.add('emi','4',[
{id:'emi4a',name:'Désinformation, rumeur et manipulation',icon:'🎭',domain:'Esprit critique',
 refs:[REF_CLEMI+' — culture informationnelle',EDU],
 tip:'Une désinformation est volontaire, une mésinformation est une erreur de bonne foi : dans les deux cas, la vérification avant de partager est la même.',
 c:C(`En 4e, on distingue plus précisément les types de fausses informations : la <b>désinformation</b> (diffusée volontairement pour tromper), la <b>mésinformation</b> (une erreur partagée sans intention de nuire) et la <b>rumeur</b> (une information non vérifiée qui circule de bouche à oreille ou en ligne).`,
  [T('Désinformation et mésinformation',`<p>La <b>désinformation</b> est créée ou diffusée <b>volontairement</b> pour tromper, souvent dans un but politique, financier ou pour nuire à quelqu’un. La <b>mésinformation</b> est le partage d’une information fausse par quelqu’un qui la croit vraie, <b>sans intention de nuire</b>. Dans les deux cas, le résultat (une fausse information diffusée) peut être le même.</p>`),
   T('Les techniques de manipulation',`<p>Certaines techniques reviennent souvent : <b>décontextualiser</b> une image ou une citation, <b>inventer</b> un faux expert ou une fausse étude, <b>exagérer</b> des chiffres réels, utiliser un <b>faux compte</b> qui imite un média connu. Comprendre ces techniques aide à les repérer plus vite.</p>`)],
  [{q:'Un faux compte, avec un nom et un logo presque identiques à ceux d’un grand journal, publie une fausse information.',s:['Le nom et le logo imitent un média connu pour tromper.','C’est une technique de désinformation (manipulation volontaire).','Vérifier l’adresse exacte du compte ou du site permet de repérer la supercherie.']}],
  ['Je distingue désinformation (volontaire) et mésinformation (erreur).','Je repère les techniques de manipulation courantes.','Je me méfie des comptes qui imitent un média connu.','Je vérifie avant de partager, dans tous les cas.'],
  ['Croire qu’une fausse information n’est jamais partagée de bonne foi.','Ne pas vérifier l’adresse exacte d’un compte qui semble officiel.','Penser qu’un faux expert cité ne peut pas exister.'],
  ['Désinformation (volontaire) vs mésinformation (erreur).','Techniques : décontextualiser, inventer, exagérer, imiter.','Toujours vérifier avant de partager.']),
 g:mix([sort({'Désinformation':['créer une fausse vidéo pour nuire à une personnalité','inventer une fausse étude scientifique pour influencer l’opinion'],'Mésinformation':['partager par erreur une ancienne information en pensant qu’elle est récente','recommander à un ami un conseil de santé faux, cru vrai de bonne foi']},{q:'« %s » est un exemple de…'}),2],
  [bank([
   ['La désinformation est diffusée…','volontairement, pour tromper',['toujours par erreur','uniquement par des robots','uniquement à la télévision'],'Elle poursuit souvent un but précis.'],
   ['La mésinformation correspond à…','le partage, de bonne foi, d’une information fausse qu’on croyait vraie',['une information toujours vraie','une technique de piratage informatique','un type de virus'],'Il n’y a pas d’intention de tromper.'],
   ['Un faux compte qui imite le nom et le logo d’un grand journal cherche à…','faire croire que l’information vient d’une source fiable',['améliorer la qualité de l’information','aider les vrais journalistes','protéger les lecteurs'],'C’est une technique de manipulation fréquente.'],
   ['Citer un « expert » qui n’existe pas est une technique qui vise à…','donner une fausse autorité à une information',['rendre l’information plus courte','améliorer la mise en page','prouver que l’information est vraie'],'Une fausse autorité peut tromper un lecteur pressé.'],
   ['Une rumeur se caractérise par…','une information non vérifiée qui circule sans source claire',['une information toujours confirmée par un média','un communiqué officiel','une publicité'],'Elle se transmet souvent de façon informelle.'],
   ['Pourquoi vérifier l’adresse exacte d’un compte ou d’un site qui semble officiel ?','car un faux compte peut imiter un nom et un logo connus',['ce n’est jamais nécessaire','parce que l’adresse n’a aucune importance','parce que tous les comptes sont automatiquement vérifiés'],'Un détail dans l’adresse peut révéler une imitation.',2],
   {tf:'Une fausse information peut être partagée sans aucune intention de nuire.',v:true,e:'C’est le cas de la mésinformation.'},
   {tf:'Décontextualiser une image vraie ne peut jamais être considéré comme une manipulation.',v:false,e:'Sortir une image vraie de son contexte reste une technique de manipulation.',d:2},
   ['Exagérer un chiffre réel pour renforcer un message est…','une technique de manipulation même si le chiffre de départ est vrai',['toujours honnête puisque le chiffre existe','sans aucune conséquence','une preuve de rigueur'],'La déformation d’un chiffre réel trompe autant qu’une invention totale.',2]]),2])},

{id:'emi4b',name:'Algorithmes de recommandation et bulles de filtres',icon:'🧮',domain:'Plateformes',
 refs:[REF_CLEMI+' — culture technique et numérique',EDU],
 tip:'Un algorithme de recommandation te montre surtout ce que tu as déjà aimé ou regardé : pour voir d’autres points de vue, il faut parfois chercher activement ailleurs.',
 c:C(`Sur les réseaux sociaux et les plateformes vidéo, un <b>algorithme</b> choisit automatiquement ce qu’on voit en priorité, en fonction de nos comportements passés. Ce fonctionnement peut créer une <b>bulle de filtres</b> : on finit par voir surtout des contenus qui confirment ce que l’on pense déjà.`,
  [T('Comment fonctionne la recommandation',`<p>Un <b>algorithme de recommandation</b> analyse ce qu’on a déjà regardé, « liké » ou commenté, pour proposer des contenus <b>similaires</b>, dans le but de maximiser le temps passé sur la plateforme. Il ne choisit pas en fonction de la vérité ou de l’importance d’une information, mais en fonction de ce qui a des chances de nous intéresser.</p>`),
   T('La bulle de filtres',`<p>La <b>bulle de filtres</b> est l’effet par lequel une personne voit de moins en moins de contenus qui contredisent ses opinions, et de plus en plus de contenus qui les confirment. Cela peut renforcer des <b>idées fausses</b> ou des <b>stéréotypes</b> sans qu’on s’en rende compte. Chercher activement d’autres points de vue permet d’en sortir partiellement.</p>`)],
  [{q:'Un élève ne voit, sur son fil d’actualité, que des contenus qui confirment son opinion sur un sujet. Pourquoi ?',s:['L’algorithme lui propose ce qu’il a déjà « liké » ou regardé.','Cela crée une bulle de filtres qui renforce son opinion de départ.','Chercher volontairement d’autres sources et points de vue permet d’en sortir.']}],
  ['Je comprends comment fonctionne un algorithme de recommandation.','Je sais ce qu’est une bulle de filtres et comment elle se forme.','Je repère que mon fil d’actualité n’est pas représentatif de tous les points de vue.','Je cherche volontairement d’autres sources pour élargir ma vision.'],
  ['Croire que son fil d’actualité montre « tout » sur un sujet.','Penser qu’un algorithme choisit en fonction de la vérité.','Ne jamais chercher d’autres points de vue par soi-même.'],
  ['Algorithme = contenus similaires au comportement passé.','Bulle de filtres : renforcement des opinions déjà présentes.','Chercher activement d’autres points de vue.']),
 g:mix([bank([
  ['Un algorithme de recommandation choisit les contenus proposés en fonction de…','ce que l’utilisateur a déjà regardé, aimé ou commenté',['la vérité du contenu','l’ordre alphabétique des titres','un tirage totalement aléatoire'],'Il cherche à proposer des contenus qui retiennent l’attention.'],
  ['Une bulle de filtres désigne…','le fait de voir de plus en plus de contenus qui confirment ses opinions déjà présentes',['un filtre à café','une application de retouche photo','un virus informatique'],'Elle se forme progressivement selon les habitudes de navigation.'],
  ['Pourquoi un algorithme ne choisit-il pas en priorité « la vérité » ?','parce qu’il est conçu pour maximiser l’intérêt et le temps passé, pas pour vérifier les faits',['parce que c’est interdit par la loi','parce que la vérité n’existe pas','parce qu’il choisit toujours au hasard'],'Son objectif premier est différent de la vérification journalistique.'],
  ['Pour sortir partiellement d’une bulle de filtres, on peut…','chercher activement des sources et des points de vue différents',['se contenter de son fil d’actualité habituel','suivre uniquement des comptes qui pensent comme soi','ignorer totalement le problème'],'Une démarche active permet d’élargir sa vision.'],
  ['Deux personnes qui suivent des comptes différents sur un même sujet voient-elles exactement le même contenu recommandé ?','non, les recommandations sont personnalisées',['oui, toujours la même chose','oui, car l’algorithme est identique pour tous','oui, sauf le week-end'],'La personnalisation dépend de l’historique de chacun.',2],
  {tf:'Un algorithme de recommandation peut renforcer des stéréotypes sans intention explicite de ses concepteurs.',v:true,e:'C’est un effet indirect du fonctionnement par similarité.',d:2},
  {tf:'Les contenus recommandés sont toujours représentatifs de l’ensemble des opinions qui existent sur un sujet.',v:false,e:'Ils reflètent surtout ce qui correspond au profil de l’utilisateur.'},
  ['« Liker » beaucoup de contenus d’un même type influence-t-il les prochaines recommandations ?','oui, l’algorithme s’adapte au comportement observé',['non, les recommandations sont fixes','non, elles sont tirées au hasard chaque jour','non, l’algorithme ignore les « j’aime »'],'Chaque interaction nourrit le profil utilisé par l’algorithme.'],
  ['Deux amis qui ont des habitudes de navigation très différentes verront-ils le même fil de recommandations sur une plateforme ?','non, probablement pas',['oui, toujours strictement identique','oui, car l’algorithme est unique pour tous','oui, car cela ne dépend que de l’âge'],'La personnalisation dépend de l’historique propre à chacun.'],
  ['Pourquoi un contenu extrême ou polarisant est-il parfois davantage recommandé ?','parce qu’il suscite plus de réactions et retient davantage l’attention',['parce qu’il est toujours plus exact','parce que la loi l’impose','parce qu’il coûte moins cher à produire'],'L’engagement généré influence la mise en avant algorithmique.',2],
  ['S’abonner volontairement à des comptes aux points de vue variés sur un sujet permet…','d’élargir la diversité des contenus proposés par l’algorithme',['de bloquer totalement l’algorithme','de supprimer son compte automatiquement','de rendre le fil d’actualité totalement aléatoire'],'Les abonnements influencent ce qui est ensuite recommandé.',2],
  ['Le temps passé à regarder un contenu jusqu’à la fin influence-t-il les recommandations futures ?','oui, c’est un signal pris en compte par de nombreux algorithmes',['non, seul le nombre de clics compte','non, aucun signal de ce type n’est utilisé','non, cela ne dépend que de la date de publication'],'Le temps de visionnage est un indicateur d’intérêt largement exploité.',2]]),2])},

{id:'emi4c',name:'Influence, publicité et placement de produit',icon:'🛍️',domain:'Économie des médias',
 refs:[REF_CLEMI+' — culture sociale et citoyenne',EDU],
 tip:'Un contenu doit indiquer clairement s’il est un partenariat commercial : la mention « #Publicité » ou « #Sponsorisé » doit être visible dès le début, pas cachée en petit dans la description.',
 c:C(`De nombreux créateurs de contenu (influenceurs, youtubeurs, chroniqueurs) sont <b>rémunérés</b> par des marques pour présenter un produit. Reconnaître cette <b>influence commerciale</b>, souvent appelée <b>placement de produit</b> ou partenariat, permet de garder un regard critique.`,
  [T('Publicité, partenariat, placement de produit',`<p>La <b>publicité classique</b> est clairement identifiée comme telle (bandeau, pré-roll). Le <b>partenariat rémunéré</b> consiste, pour un créateur, à parler d’un produit en échange d’argent ou de cadeaux : la loi impose en principe de le signaler (mention « Publicité », « Partenariat »). Le <b>placement de produit</b> intègre discrètement un produit dans un contenu (une émission, une vidéo) sans toujours que cela soit mis en avant.</p>`),
   T('Garder un regard critique',`<p>Un avis donné en échange d’une rémunération n’est pas forcément <b>objectif</b> : le créateur a un intérêt financier à présenter le produit favorablement. On vérifie si une mention de partenariat apparaît, on compare avec des <b>avis indépendants</b>, et on garde en tête que l’enthousiasme affiché peut être en partie commercial.</p>`)],
  [{q:'Une vidéo très enthousiaste présente un nouveau jeu vidéo, avec en petit, dans la description, la mention « partenariat rémunéré ».',s:['Le créateur a été payé pour présenter ce jeu : c’est un partenariat commercial.','Son avis peut être influencé par cette rémunération.','Comparer avec des avis indépendants donne une vision plus complète.']}],
  ['Je repère les mentions de partenariat ou de publicité.','Je comprends qu’un avis rémunéré peut manquer d’objectivité.','Je connais la différence entre publicité classique et placement de produit.','Je compare avec des avis indépendants quand c’est possible.'],
  ['Croire qu’un avis très positif est forcément sincère et désintéressé.','Ignorer une mention de partenariat cachée en petit texte.','Confondre l’enthousiasme affiché avec une évaluation objective.'],
  ['Publicité classique = clairement signalée.','Partenariat rémunéré = en principe signalé.','Placement de produit = discret.']),
 g:mix([bank([
  ['Un « partenariat rémunéré » signifie que le créateur de contenu…','a été payé ou récompensé pour présenter un produit',['travaille gratuitement par passion uniquement','n’a aucun lien avec la marque présentée','refuse tout avantage de la marque'],'Cela peut influencer son avis.'],
  ['La loi impose en principe que les partenariats commerciaux soient…','clairement signalés au public',['totalement cachés','interdits sans exception','ignorés par les plateformes'],'La transparence protège les consommateurs.'],
  ['Le placement de produit consiste à…','intégrer discrètement un produit dans un contenu',['interdire la présence de tout produit','annoncer un produit avec un gros bandeau « Publicité »','supprimer toute mention de marque'],'Il est souvent moins visible qu’une publicité classique.'],
  ['Un avis très enthousiaste sur un produit, donné dans le cadre d’un partenariat rémunéré, est-il nécessairement totalement objectif ?','pas nécessairement',['oui, toujours totalement objectif','oui, car l’argent ne change jamais un avis','oui, par définition d’un partenariat'],'L’intérêt financier peut influencer le ton employé.'],
  ['Pour avoir un avis plus complet sur un produit présenté par un créateur rémunéré, on peut…','comparer avec des avis indépendants, non rémunérés',['se fier uniquement à cette seule vidéo','acheter le produit immédiatement sans réfléchir','ignorer tout avis sur le produit'],'Le croisement des avis donne une vision plus équilibrée.'],
  {tf:'Une mention de partenariat cachée en tout petit dans la description d’une vidéo respecte pleinement l’esprit de la transparence attendue.',v:false,e:'Une mention peu visible ne permet pas réellement d’informer le public.',d:2},
  {tf:'Tous les créateurs de contenu qui parlent d’un produit sont rémunérés pour le faire.',v:false,e:'Beaucoup d’avis restent spontanés et non rémunérés.'},
  ['Recevoir un produit gratuitement de la part d’une marque, sans être payé en argent, constitue-t-il un avantage à signaler ?','oui, c’est une forme d’avantage qui doit en principe être mentionnée',['non, seul l’argent compte','non, un cadeau n’influence jamais un avis','non, ce n’est jamais nécessaire'],'Un cadeau peut aussi influencer un avis, même sans paiement direct.',2],
  ['Un influenceur qui refuse de présenter un produit auquel il n’a pas cru, malgré une offre de rémunération, fait preuve de…','intégrité éditoriale',['naïveté','erreur professionnelle','manque de compétence'],'Préserver la sincérité de son avis reste une démarche responsable.'],
  ['Voir le même produit présenté très positivement par de nombreux créateurs en même temps peut indiquer…','une campagne de partenariats coordonnée par la marque',['toujours une coïncidence totale','une preuve certaine de la qualité du produit','une erreur de l’algorithme'],'Les marques organisent parfois des campagnes simultanées.',2],
  ['Un « avis sponsorisé » doit-il être traité exactement comme un avis totalement spontané et désintéressé ?','non, il mérite une attention particulière du fait de la rémunération perçue',['oui, c’est rigoureusement identique','oui, car l’argent ne change jamais rien','oui, aucune nuance n’est nécessaire'],'La rémunération peut influencer, même inconsciemment, le discours tenu.'],
  ['Un influenceur qui ne précise jamais ses partenariats commerciaux, contrairement à ce que prévoit la loi, prend le risque…','de sanctions prévues par la réglementation sur la publicité et la protection des consommateurs',['d’aucune conséquence','d’une récompense officielle','d’une augmentation automatique de ses revenus'],'La transparence commerciale est encadrée par la loi.',3]]),2])},

{id:'emi4d',name:'Liberté d’expression et responsabilités',icon:'⚖️',domain:'Droit',
 refs:[REF_CLEMI+' — culture sociale et citoyenne',LOI1881,EDU],
 tip:'La liberté d’expression ne protège pas les propos qui appellent à la haine, à la violence ou qui diffament : elle s’exerce dans le cadre fixé par la loi.',
 c:C(`La <b>liberté d’expression</b> permet à chacun de donner son avis et aux médias d’informer sans être censurés arbitrairement par l’État. Mais cette liberté s’exerce dans un <b>cadre légal</b> : elle n’autorise pas tout, et elle s’accompagne de <b>responsabilités</b>.`,
  [T('Un droit encadré par la loi',`<p>En France, la liberté d’expression et de la presse est garantie, notamment par la loi du 29 juillet 1881, mais la loi interdit certains propos : la <b>diffamation</b> (affirmer un fait faux qui nuit à la réputation de quelqu’un), l’<b>injure</b>, l’<b>incitation à la haine</b> ou à la violence, et la <b>provocation</b> à des actes interdits. Ces limites s’appliquent aussi bien aux journalistes qu’à n’importe quel internaute.</p>`),
   T('Responsabilité sur Internet',`<p>Publier ou partager un contenu illégal (insulte, appel à la haine, fausse accusation) peut entraîner des <b>conséquences juridiques</b> pour son auteur, y compris en ligne. La liberté d’expression ne protège pas un propos illégal simplement parce qu’il est publié sur un réseau social plutôt que dans un journal.</p>`)],
  [{q:'Un message en ligne accuse publiquement une personne, nommément, d’un fait grave et faux.',s:['Ce message peut constituer une diffamation.','La liberté d’expression ne protège pas ce type de propos.','La personne visée peut engager une action en justice.']}],
  ['Je connais le principe de la liberté d’expression.','Je sais que des limites légales existent (diffamation, injure, incitation à la haine).','Je comprends que ces limites s’appliquent aussi sur Internet.','Je mesure ma responsabilité avant de publier un contenu.'],
  ['Croire que « c’est juste Internet, ça ne compte pas ».','Penser que la liberté d’expression autorise tout propos sans limite.','Ignorer qu’une fausse accusation publique peut constituer une diffamation.'],
  ['Liberté d’expression encadrée par la loi.','Diffamation, injure, incitation à la haine : interdites.','Conséquences possibles, y compris en ligne.']),
 g:mix([bank([
  ['La diffamation consiste à…','affirmer publiquement un fait faux qui nuit à la réputation de quelqu’un',['donner une opinion personnelle argumentée','citer une source fiable','critiquer une œuvre artistique'],'Elle se distingue d’une critique légitime.'],
  ['La liberté d’expression permet-elle d’appeler à la violence contre un groupe de personnes ?','non, c’est interdit par la loi',['oui, sans aucune limite','oui, si c’est en ligne','oui, si c’est présenté comme une blague'],'L’incitation à la haine ou à la violence constitue une limite légale.'],
  ['Publier un contenu illégal (insulte grave, appel à la haine) sur un réseau social peut-il avoir des conséquences légales ?','oui, comme pour toute autre publication',['non, Internet échappe à toute loi','non, seuls les journalistes risquent des poursuites','non, cela ne concerne que les adultes'],'La loi s’applique aussi en ligne.'],
  ['Critiquer de façon argumentée un livre ou un film relève…','de la liberté d’expression, de façon légitime',['toujours d’une diffamation','d’une infraction systématique','d’une incitation à la haine'],'Une critique légitime diffère d’une accusation fausse ou d’une insulte.'],
  ['Quelle loi garantit historiquement la liberté de la presse en France ?','la loi du 29 juillet 1881',['le règlement intérieur des collèges','une décision d’un seul média','aucune loi particulière'],'Un texte fondateur, encore en vigueur aujourd’hui.',2],
  {tf:'La liberté d’expression autorise à dire absolument tout, sans aucune exception.',v:false,e:'Elle est encadrée par des limites légales précises.'},
  {tf:'Une fausse accusation publique peut constituer une diffamation punie par la loi.',v:true,e:'La fausseté du fait affirmé et le préjudice causé sont des éléments déterminants.',d:2},
  ['L’injure se distingue de la diffamation parce qu’elle…','consiste en une expression outrageante sans affirmation d’un fait précis',['est toujours plus grave que la diffamation','n’existe pas dans la loi française','se limite aux propos écrits uniquement'],'La diffamation repose sur l’affirmation d’un fait, l’injure non.',2],
  ['Une personne visée par des propos diffamatoires en ligne peut…','engager une action en justice, y compris contre l’auteur d’une publication sur Internet',['seulement se plaindre à ses amis sans aucun recours','seulement supprimer son propre compte','seulement ignorer la situation'],'La loi protège les victimes, quel que soit le support utilisé.'],
  ['Partager soi-même un message diffamatoire écrit par quelqu’un d’autre, sans le vérifier, est…','une action qui engage aussi sa propre responsabilité',['toujours sans conséquence pour celui qui partage','une protection automatique contre toute poursuite','obligatoirement légal si le message existe déjà'],'Relayer un contenu illégal n’efface pas sa propre responsabilité.',2],
  ['Le fait d’être mineur dispense-t-il totalement des conséquences légales d’une publication illégale en ligne ?','non, des règles spécifiques existent mais une responsabilité peut être engagée',['oui, totalement et dans tous les cas','oui, la loi ne s’applique jamais aux mineurs','oui, uniquement après 16 ans'],'Des dispositifs adaptés aux mineurs existent, sans supprimer toute responsabilité.',3],
  ['Modifier légèrement l’orthographe d’un nom pour « contourner » une interdiction de diffamer reste-t-il risqué légalement ?','oui, si la personne visée demeure clairement identifiable',['non, cela rend toute poursuite impossible','non, c’est une méthode totalement sûre','non, cela change complètement la situation juridique'],'L’identification reste possible malgré une légère modification du nom.',3]]),2])},

{id:'emi4e',name:'Données personnelles et traçage',icon:'🕵️',domain:'Vie privée',
 refs:[REF_CLEMI+' — culture technique et numérique',EDU],
 tip:'Les cookies, les autorisations d’applications et l’historique de navigation permettent à des entreprises de dresser un profil assez précis de tes habitudes : vérifier et limiter ces réglages fait partie de la protection de sa vie privée.',
 c:C(`Chaque navigation, chaque clic, chaque recherche peut être <b>enregistré</b> par des sites et des applications. Ce <b>traçage</b> permet de dresser un profil des habitudes d’un utilisateur, souvent utilisé à des fins publicitaires. Comprendre ce mécanisme aide à mieux protéger ses <b>données personnelles</b>.`,
  [T('Comment fonctionne le traçage',`<p>Les <b>cookies</b> sont de petits fichiers déposés par un site pour mémoriser des informations (connexion, préférences, navigation). Les <b>traceurs publicitaires</b> suivent la navigation d’un utilisateur sur plusieurs sites pour lui proposer des publicités <b>ciblées</b>. Les applications demandent parfois des <b>autorisations</b> (localisation, contacts, micro) qui, mal réglées, permettent de collecter beaucoup d’informations.</p>`),
   T('Se protéger',`<p>Le <b>RGPD</b> (règlement européen de 2018) oblige les sites à demander le consentement avant de déposer certains cookies, et donne des droits (accès, effacement) sur ses données ; la <b>CNIL</b> veille à son application en France. On peut refuser les cookies non nécessaires, limiter les autorisations des applications, et vérifier régulièrement les paramètres de confidentialité de ses comptes.</p>`)],
  [{q:'Une application de calculatrice demande l’accès à la localisation, aux contacts et au micro. Que faire ?',s:['Une calculatrice n’a besoin d’aucune de ces autorisations pour fonctionner.','Ces demandes sont disproportionnées par rapport à son usage.','Refuser ces autorisations ou choisir une autre application plus respectueuse.']}],
  ['Je comprends ce qu’est un cookie et un traceur publicitaire.','Je vérifie les autorisations demandées par une application.','Je connais le rôle du RGPD et de la CNIL.','Je règle mes paramètres de confidentialité régulièrement.'],
  ['Accepter systématiquement tous les cookies sans réfléchir.','Accorder toutes les autorisations demandées sans vérifier leur utilité.','Ignorer que des entreprises peuvent dresser un profil de ses habitudes.'],
  ['Cookies, traceurs publicitaires, publicité ciblée.','RGPD (2018), CNIL.','Refuser les cookies non nécessaires, limiter les autorisations.']),
 g:mix([bank([
  ['Un cookie, sur un site web, est…','un petit fichier qui mémorise des informations sur la navigation',['un biscuit offert par le site','un virus informatique','un mot de passe obligatoire'],'Il peut servir à la connexion ou à la publicité ciblée.'],
  ['Un traceur publicitaire permet…','de suivre la navigation d’un utilisateur sur plusieurs sites pour cibler les publicités',['de protéger les données personnelles','d’accélérer la connexion Internet','de corriger les fautes d’orthographe'],'Il relie les comportements sur différents sites.'],
  ['Le RGPD est…','un règlement européen de 2018 qui protège les données personnelles',['une application de messagerie','un virus connu','un moteur de recherche'],'Il encadre la collecte et l’usage des données.'],
  ['La CNIL est chargée, en France, de…','veiller au respect des règles de protection des données personnelles',['distribuer le courrier','gérer les transports en commun','organiser les examens scolaires'],'Commission nationale de l’informatique et des libertés.',2],
  ['Une application de calculatrice qui demande l’accès au micro et à la localisation est…','suspecte, car ces autorisations ne sont pas nécessaires à son usage',['normale, toutes les applications ont besoin de cela','obligatoire pour fonctionner correctement','sans aucun risque'],'Les autorisations doivent correspondre à l’usage réel de l’application.'],
  {tf:'Le RGPD impose en principe de demander le consentement avant de déposer certains cookies.',v:true,e:'C’est l’un des principes du règlement.'},
  {tf:'Refuser les cookies non nécessaires empêche systématiquement l’utilisation d’un site.',v:false,e:'La plupart des sites restent utilisables même en refusant les cookies non essentiels.',d:2},
  ['Le droit d’accès et le droit d’effacement sont des droits garantis par…','le RGPD',['le règlement intérieur du collège','aucun texte particulier','une simple habitude des entreprises'],'Ils permettent de consulter et de faire supprimer certaines données personnelles.',2],
  ['Une publicité « ciblée », qui correspond précisément à une recherche récente, montre que…','la navigation a probablement été suivie par des traceurs',['c’est une pure coïncidence sans lien avec la navigation','cela ne peut jamais arriver','la publicité a été choisie au hasard'],'Le traçage explique souvent cette précision.'],
  ['Naviguer en mode « privé » dans un navigateur empêche-t-il totalement tout traçage par des entreprises tierces ?','non, cela limite surtout l’enregistrement local de l’historique',['oui, totalement et dans tous les cas','oui, cela rend invisible sur tout Internet','oui, aucun site ne peut plus suivre la navigation'],'D’autres méthodes de traçage peuvent persister malgré ce mode.',2],
  ['Utiliser un même mot de passe et un même pseudonyme sur plusieurs sites peut faciliter…','le croisement de profils entre différents services par des tiers',['la protection totale de l’identité','l’impossibilité de tout traçage','rien de particulier'],'Des éléments communs facilitent le rapprochement entre comptes.',3],
  ['Les paramètres de confidentialité d’un compte doivent-ils être vérifiés une seule fois, définitivement ?','non, il est utile de les revérifier de temps en temps, car ils peuvent changer',['oui, une seule fois pour toujours','oui, car ils ne changent jamais','oui, dès la création du compte uniquement'],'Les services modifient parfois leurs réglages par défaut au fil du temps.']]),2])},

{id:'emi4f',name:'Enquêter, sourcer et publier',icon:'🕵️‍♀️',domain:'Journalisme',
 refs:[REF_CLEMI+' — culture médiatique et informationnelle',EDU],
 tip:'Un bon travail journalistique s’appuie sur plusieurs sources recoupées, cite ses sources clairement et distingue ce qui est confirmé de ce qui reste une hypothèse.',
 c:C(`En 4e, on approfondit la <b>démarche d’enquête</b> journalistique : comment un journaliste collecte des informations, les vérifie, et les présente dans un article <b>sourcé</b>, en distinguant ce qui est établi de ce qui reste incertain.`,
  [T('La démarche d’enquête',`<p>Une enquête commence par une <b>question</b> précise. Le journaliste recueille des informations auprès de plusieurs <b>témoins</b> ou <b>documents</b>, recoupe ces informations entre elles, et vérifie les <b>faits</b> avant de les publier. Il distingue ce qui est <b>confirmé</b> (plusieurs sources concordantes), ce qui reste une <b>hypothèse</b>, et ce qui est son <b>opinion</b> personnelle.</p>`),
   T('Sourcer un article',`<p>Un article bien sourcé indique d’où viennent les informations (« selon un rapport officiel », « d’après un témoin présent », « d’après nos vérifications »). Certaines sources restent <b>anonymes</b> pour protéger une personne, mais le média garantit alors en avoir vérifié la fiabilité auprès de sa rédaction.</p>`),
   T('Déontologie',`<p>Le <b>Conseil de déontologie journalistique et de médiation</b> et les chartes professionnelles rappellent les règles : vérifier avant de publier, corriger une erreur, protéger certaines sources, distinguer faits et commentaires.</p>`)],
  [{q:'Un article affirme : « Selon trois sources indépendantes consultées, le projet serait reporté. Une source proche du dossier estime que ce retard est injustifié (avis personnel de la source). »',s:['« Trois sources indépendantes » signale un recoupement sérieux.','« serait » indique une information encore incertaine.','L’avis sur le retard est présenté comme une opinion, pas comme un fait établi.']}],
  ['Je comprends les étapes d’une démarche d’enquête journalistique.','Je distingue fait confirmé, hypothèse et opinion dans un article.','Je repère comment un article cite ses sources.','Je comprends pourquoi une source peut rester anonyme.'],
  ['Confondre une hypothèse présentée avec prudence et un fait certain.','Croire qu’un article sans aucune source est aussi fiable qu’un article sourcé.','Penser qu’une source anonyme n’est jamais vérifiée par le média.'],
  ['Question, témoins, recoupement, vérification.','Fait confirmé ≠ hypothèse ≠ opinion.','Sources parfois anonymes, mais vérifiées par la rédaction.']),
 g:mix([sort({'Fait confirmé (recoupé par plusieurs sources)':['la réunion a eu lieu le 10 mars, confirmée par trois témoins','le rapport officiel, consulté par la rédaction, indique ce chiffre'],'Hypothèse ou opinion (à distinguer d’un fait établi)':['le projet serait reporté, selon une seule source non confirmée','un expert estime que cette décision est une erreur (avis personnel)']},{q:'« %s » relève de…'}),2],
  [bank([
   ['Pourquoi un journaliste recoupe-t-il plusieurs sources avant de publier ?','pour vérifier qu’une information n’est pas isolée ou erronée',['pour perdre du temps','ce n’est jamais nécessaire','pour rendre l’article plus long'],'Le recoupement renforce la fiabilité.'],
   ['L’emploi du conditionnel (« serait », « aurait ») dans un article signale…','une information encore incertaine, non totalement confirmée',['une erreur grammaticale','une information totalement fausse','une opinion politique'],'C’est une nuance journalistique précise.'],
   ['Une source anonyme dans un article signifie-t-elle que l’information n’a pas été vérifiée ?','non, le média garantit en principe l’avoir vérifiée auprès de sa rédaction',['oui, toujours','oui, par définition','oui, car l’anonymat empêche toute vérification'],'L’anonymat protège la source, pas la rigueur de la vérification.',2],
   ['Que fait un article qui distingue clairement fait, hypothèse et opinion ?','il informe le lecteur du degré de certitude de chaque élément',['il complique inutilement la lecture','il cache des informations au lecteur','il ne respecte aucune règle journalistique'],'Cette distinction est une marque de rigueur.'],
   ['Si une rédaction découvre une erreur après publication, la pratique rigoureuse est de…','publier un rectificatif',['ne rien faire','supprimer l’article sans explication','nier l’erreur publiquement'],'La correction transparente fait partie de la déontologie.',2],
   {tf:'Un article journalistique rigoureux peut contenir à la fois des faits confirmés et des éléments encore incertains, à condition de les distinguer clairement.',v:true,e:'La nuance fait partie du travail d’information.'},
   {tf:'Toutes les sources citées dans un article doivent obligatoirement être nommées publiquement.',v:false,e:'Certaines sources restent anonymes pour des raisons de protection, tout en étant vérifiées par la rédaction.',d:2},
   ['Le Conseil de déontologie journalistique et de médiation (CDJM) a pour rôle…','d’examiner le respect des règles professionnelles par les médias',['de vendre des espaces publicitaires','de fixer le prix des journaux','d’organiser des concours de photographie'],'Il peut être saisi en cas de manquement à la déontologie.',3]]),2])}
]);

MQ.add('emi','3',[
{id:'emi3a',name:'Fiabilité d’une source et méthode de fact-checking',icon:'🔬',domain:'Esprit critique',
 refs:[REF_CLEMI+' — culture informationnelle',EDU],
 tip:'La méthode des journalistes qui vérifient les faits (« fact-checking ») : remonter à la source primaire, recouper au moins deux sources indépendantes, vérifier la date et le contexte, et publier le résultat même si c’est « c’est faux » ou « c’est vrai, mais… ».',
 c:C(`En 3e, on systématise une véritable <b>méthode de vérification</b>, proche de celle utilisée par les journalistes spécialisés dans la vérification des faits (« <b>fact-checking</b> »), pour juger la fiabilité d’une information complexe ou polémique.`,
  [T('La méthode du fact-checking',`<p>1. <b>Identifier l’affirmation</b> précise à vérifier. 2. <b>Remonter à la source primaire</b> (l’étude, le document, la déclaration d’origine). 3. <b>Recouper</b> avec au moins une autre source indépendante et fiable. 4. Vérifier la <b>date</b> et le <b>contexte</b>. 5. Conclure de façon nuancée : « vrai », « faux », « en partie vrai », « invérifiable en l’état ».</p>`),
   T('Les rubriques de vérification',`<p>De nombreux médias disposent d’une <b>rubrique de vérification des faits</b>, qui analyse des affirmations virales, des discours, ou des images douteuses. Leur travail est public et sourcé : on peut lire leur méthode et leurs preuves, ce qui permet de vérifier leur propre sérieux.</p>`)],
  [{q:'Une affirmation virale dit : « Cette étude prouve que [tel produit] est dangereux. » Applique la méthode de vérification.',s:['Identifier l’affirmation précise : que dit vraiment l’étude citée ?','Remonter à l’étude elle-même plutôt qu’à un résumé qui la déforme peut-être.','Vérifier si l’étude est récente, sérieuse, et si d’autres études la confirment.']}],
  ['Je sais identifier précisément l’affirmation à vérifier.','Je remonte à la source primaire plutôt qu’à un résumé.','Je recoupe avec au moins une source indépendante.','Je conclus de façon nuancée plutôt que par un simple « vrai » ou « faux ».'],
  ['Se contenter d’un résumé qui peut déformer l’étude d’origine.','Croire qu’une seule source suffit à confirmer une affirmation complexe.','Conclure de façon trop tranchée sur un sujet incertain.'],
  ['Méthode en 5 étapes : affirmation, source primaire, recoupement, date/contexte, conclusion nuancée.','Rubriques de fact-checking : publiques et sourcées.','Nuancer : vrai / faux / en partie vrai / invérifiable.']),
 g:mix([d=>order('Remets dans l’ordre la méthode de vérification d’une affirmation :',['Identifier l’affirmation précise','Remonter à la source primaire','Recouper avec une autre source indépendante','Vérifier la date et le contexte','Conclure de façon nuancée'],{expl:'Affirmation → source primaire → recoupement → date/contexte → conclusion.'}),2],
  [bank([
   ['La première étape d’une vérification méthodique est…','identifier précisément l’affirmation à vérifier',['publier immédiatement un avis','partager l’information à tout le monde','choisir une conclusion au hasard'],'Une affirmation vague est difficile à vérifier.'],
   ['Pourquoi remonter à la source primaire plutôt qu’à un résumé qui en parle ?','un résumé peut déformer ou simplifier le contenu d’origine',['un résumé est toujours plus fiable que l’original','ce n’est jamais nécessaire','la source primaire n’existe jamais'],'Le résumé peut introduire des erreurs ou des raccourcis.'],
   ['Une conclusion de fact-checking peut être…','« en partie vrai » ou « invérifiable en l’état »',['uniquement « vrai » ou « faux », sans nuance possible','toujours « faux »','toujours « vrai »'],'La réalité est parfois plus nuancée qu’un simple oui ou non.'],
   ['Un média spécialisé dans la vérification des faits rend-il publique sa méthode ?','oui, en général, avec ses preuves et ses sources',['non, c’est toujours secret','non, jamais','non, cela changerait selon le jour'],'La transparence permet de vérifier son sérieux à son tour.'],
   ['Recouper une affirmation avec « une autre source » qui a simplement copié la première est-il suffisant ?','non, il faut une source réellement indépendante',['oui, cela suffit toujours','oui, le nombre de répétitions suffit','oui, si la source est populaire'],'La copie n’ajoute pas de vérification réelle.',2],
   {tf:'Une méthode de vérification rigoureuse peut parfois conclure qu’une information reste « invérifiable en l’état ».',v:true,e:'Toutes les affirmations ne peuvent pas être tranchées avec certitude.'},
   {tf:'Le fact-checking consiste uniquement à dire si une information est vraie ou fausse, sans jamais expliquer pourquoi.',v:false,e:'La méthode et les preuves sont en général détaillées et publiques.',d:2},
   ['Vérifier le contexte d’une affirmation signifie notamment…','regarder dans quelle situation et à quel moment elle a été formulée',['ignorer complètement la date','se fier uniquement au ton employé','compter le nombre de partages'],'Une phrase sortie de son contexte peut changer de sens.'],
   ['Une rubrique de vérification qui se trompe et le reconnaît publiquement fait-elle preuve de sérieux ?','oui, reconnaître une erreur et la corriger est une pratique rigoureuse',['non, cela prouve son manque de fiabilité totale','non, un média sérieux ne se trompe jamais','non, il vaudrait mieux ne rien dire'],'La transparence sur les erreurs renforce la crédibilité à long terme.',2],
   ['Appliquer cette méthode de vérification demande-t-elle plus de temps qu’un simple partage immédiat ?','oui, mais ce temps réduit le risque de diffuser une erreur',['non, c’est toujours instantané','non, cela ne demande jamais aucun effort','non, cela prend toujours moins de temps que de lire l’information elle-même'],'La rigueur a un coût en temps, compensé par la fiabilité obtenue.'],
   ['Deux sources sérieuses qui arrivent à des conclusions légèrement différentes sur un même sujet complexe montrent-elles forcément qu’une des deux est malhonnête ?','non, un sujet complexe peut comporter des incertitudes même chez des sources sérieuses',['oui, l’une des deux ment nécessairement','oui, un sujet ne peut jamais comporter d’incertitude','oui, cela prouve que les deux sont peu fiables'],'La nuance scientifique ou factuelle n’est pas toujours synonyme de malhonnêteté.',3]]),2])},

{id:'emi3b',name:'Information en temps de crise et de conflit',icon:'🚨',domain:'Médias',
 refs:[REF_CLEMI+' — culture médiatique et informationnelle',EDU],
 tip:'En période de crise (catastrophe, conflit), les fausses informations et les images sorties de leur contexte circulent plus vite que d’habitude : la prudence doit être encore plus grande.',
 c:C(`En temps de <b>crise</b> (catastrophe naturelle, attentat, conflit armé) ou de <b>conflit</b>, l’information circule très vite, les émotions sont fortes, et les fausses informations se multiplient. Comprendre ces mécanismes particuliers aide à garder un regard critique au moment où c’est le plus difficile.`,
  [T('Pourquoi la désinformation augmente en temps de crise',`<p>Pendant une crise, le besoin d’information est urgent, les faits sont parfois encore <b>incertains</b>, et l’émotion pousse à partager vite. Des <b>images anciennes</b> ou venant d’un <b>autre lieu</b> sont souvent réutilisées pour illustrer un événement récent. Des <b>acteurs du conflit</b> peuvent aussi diffuser volontairement de fausses informations pour influencer l’opinion (propagande).</p>`),
   T('S’informer prudemment en temps de crise',`<p>On privilégie les <b>médias reconnus</b> qui ont des correspondants ou des méthodes de vérification, on se méfie des <b>chiffres</b> et <b>bilans</b> annoncés très tôt (souvent provisoires et corrigés ensuite), et on évite de partager une image choc avant d’avoir vérifié son origine réelle (voir le chapitre sur l’image, cadrage et manipulation).</p>`)],
  [{q:'Après une catastrophe, une photo impressionnante circule massivement, légendée comme venant de l’événement du jour.',s:['Vérifier par une recherche d’image inversée si la photo est récente et au bon endroit.','Comparer avec ce que rapportent des médias reconnus, avec correspondants sur place.','Ne pas partager avant d’avoir confirmé l’origine réelle de l’image.']}],
  ['Je comprends pourquoi la désinformation augmente en temps de crise.','Je me méfie des images sorties de leur contexte en période de crise.','Je privilégie les médias reconnus avec des méthodes de vérification.','Je reste prudent face aux premiers chiffres et bilans annoncés.'],
  ['Partager une image choquante sans vérifier son origine, « par solidarité ».','Croire qu’un bilan annoncé dans les premières heures est définitif.','Ignorer que certains acteurs d’un conflit diffusent volontairement de fausses informations.'],
  ['Crise = urgence + émotion + incertitude = plus de désinformation.','Images anciennes réutilisées, propagande.','Médias reconnus, prudence sur les premiers chiffres.']),
 g:mix([bank([
  ['Pourquoi les fausses informations se multiplient-elles en temps de crise ?','parce que le besoin d’information est urgent et l’émotion pousse à partager vite',['parce que les faits sont toujours plus simples à cette période','parce qu’il n’y a jamais de désinformation en temps calme','parce que les médias cessent de travailler'],'L’urgence et l’émotion favorisent la propagation rapide d’erreurs.'],
  ['Une image ancienne réutilisée pour illustrer un événement récent est…','une forme de désinformation par sortie de contexte',['toujours une preuve fiable','une pratique journalistique recommandée','sans conséquence'],'Elle donne une fausse impression d’actualité.'],
  ['Un bilan humain annoncé dans les premières heures d’une catastrophe est souvent…','provisoire et susceptible d’être corrigé par la suite',['toujours définitif et exact','toujours sous-estimé volontairement','sans aucune utilité'],'La situation évolue souvent dans les heures qui suivent.'],
  ['La propagande, en temps de conflit, désigne…','la diffusion volontaire d’informations biaisées pour influencer l’opinion',['un simple reportage neutre','une méthode de vérification des faits','une technique photographique'],'Elle peut venir de différents acteurs impliqués dans le conflit.'],
  ['Pourquoi privilégier des médias ayant des correspondants sur place en temps de crise ?','ils disposent d’informations vérifiées plus directement',['cela n’a aucune importance','ils sont toujours moins rapides que les réseaux sociaux','ils ne traitent jamais ce genre de sujet'],'La présence sur le terrain facilite la vérification.',2],
  {tf:'En temps de crise, il est encore plus important de vérifier une image avant de la partager.',v:true,e:'La désinformation y est plus fréquente et plus rapide.'},
  {tf:'Les chiffres annoncés dans les premières heures d’une catastrophe sont toujours parfaitement exacts.',v:false,e:'Ils sont souvent provisoires et évoluent avec le temps.',d:2},
  ['Pendant un conflit armé, les informations diffusées par chacune des parties impliquées sont-elles nécessairement neutres ?','non, elles peuvent être influencées par les intérêts de chaque partie',['oui, toujours parfaitement neutres','oui, car un conflit rend les parties plus objectives','oui, cela ne change jamais rien à l’information'],'Chaque partie a un intérêt possible à présenter les événements à son avantage.',2],
  ['Un correspondant de guerre présent sur le terrain fournit-il automatiquement une information totalement complète ?','pas forcément, sa vision reste partielle et à recouper avec d’autres sources',['oui, il voit absolument tout ce qui se passe','oui, un seul témoin suffit toujours','oui, par définition de son métier'],'Même un témoin direct a un point de vue limité à ce qu’il observe.',2],
  ['Pendant une crise, attendre quelques heures avant de partager une information non confirmée est-il toujours inutile ?','non, cela laisse le temps à une vérification ou une confirmation d’arriver',['oui, toujours inutile','oui, car l’information ne change jamais avec le temps','oui, car la rapidité prime toujours sur l’exactitude'],'La patience réduit le risque de propager une erreur.'],
  ['Les autorités officielles sont-elles la seule source fiable en temps de crise ?','non, mais elles constituent généralement une source importante à croiser avec d’autres',['oui, toujours la seule source valable','non, elles ne sont jamais fiables','non, il ne faut jamais les consulter'],'Le recoupement entre plusieurs types de sources reste la meilleure approche.'],
  ['Des témoignages d’habitants publiés sur les réseaux sociaux pendant une crise peuvent-ils apporter des informations utiles aux médias ?','oui, mais ils doivent en général être vérifiés avant d’être repris comme des faits établis',['non, jamais','oui, sans aucune vérification nécessaire','non, les témoignages n’ont jamais de valeur informative'],'Ils peuvent compléter l’information, après vérification.',2]]),2])},

{id:'emi3c',name:'Statistiques, graphiques et manipulation',icon:'📉',domain:'Données',
 refs:[REF_CLEMI+' — culture informationnelle',EDU],
 tip:'Avant de croire un graphique : regarde l’échelle des axes (commence-t-elle à zéro ?), l’unité utilisée, et la période représentée — ces choix peuvent exagérer ou minimiser une évolution réelle.',
 c:C(`Un chiffre ou un graphique semble « objectif », mais sa <b>présentation</b> peut exagérer, minimiser ou déformer une réalité, sans que les chiffres eux-mêmes soient faux. Savoir lire un graphique de façon critique fait partie de l’esprit critique en 3e.`,
  [T('Les pièges des graphiques',`<p>Une <b>échelle tronquée</b> (un axe qui ne commence pas à zéro) peut rendre une petite différence très <b>impressionnante</b>. Une <b>période choisie</b> peut cacher une tendance plus large (par exemple, choisir deux dates qui montrent une hausse alors que l’évolution générale est différente). Confondre un <b>pourcentage</b> et une <b>valeur absolue</b> peut aussi tromper (« +50 % » peut représenter très peu si la quantité de départ est faible).</p>`),
   T('Lire un chiffre avec esprit critique',`<p>On vérifie : d’où viennent les chiffres (la <b>source</b>) ? Sur quelle <b>période</b> portent-ils ? L’échelle du graphique est-elle <b>honnête</b> ? Le chiffre est-il une <b>moyenne</b>, qui peut cacher de grandes différences entre les cas ?</p>`)],
  [{q:'Un graphique montre une barre deux fois plus haute qu’une autre, mais l’axe vertical commence à 90 au lieu de 0, et les valeurs réelles sont 95 et 97.',s:['L’écart réel entre 95 et 97 est faible.','L’axe tronqué (qui ne part pas de zéro) exagère visuellement cet écart.','Regarder l’échelle de l’axe est indispensable pour juger un graphique.']}],
  ['Je vérifie si l’échelle d’un graphique commence à zéro.','Je distingue un pourcentage d’une valeur absolue.','Je vérifie la période représentée.','Je me méfie d’une moyenne qui pourrait cacher des différences importantes.'],
  ['Croire qu’un graphique est toujours honnête simplement parce qu’il contient des chiffres.','Confondre une forte hausse en pourcentage avec une forte hausse en valeur absolue.','Ignorer la période choisie pour un graphique.'],
  ['Échelle tronquée = exagération visuelle.','Pourcentage ≠ valeur absolue.','Vérifier source, période, échelle, moyenne.']),
 g:mix([d=>{const base=R(80,98),a=base,b=base+R(1,4);return ch(`Un graphique montre une grande différence entre deux valeurs : ${a} et ${b}. L’axe vertical commence à ${base-2} au lieu de 0. Cette présentation…`,'exagère visuellement un écart réel pourtant faible',['montre un écart réellement énorme','est la seule façon honnête de présenter ces données','change la valeur réelle des deux nombres'],{expl:`L’écart réel (${b-a}) est faible, mais l’axe tronqué le fait paraître énorme visuellement.`,hint:'Regarde si l’axe commence à zéro.'});},3],
  [bank([
   ['Un axe de graphique qui ne commence pas à zéro peut…','exagérer visuellement un écart réel pourtant faible',['toujours donner une impression plus juste','n’avoir aucun effet sur la lecture du graphique','rendre les chiffres faux'],'Cette technique est fréquente pour impressionner visuellement.'],
   ['« +50 % de ventes » peut représenter une faible quantité si…','le nombre de ventes de départ était très faible',['le pourcentage est toujours une preuve de grand succès','ce n’est jamais le cas','les pourcentages ne peuvent jamais tromper'],'Exemple : passer de 2 à 3 ventes, c’est +50 %.'],
   ['Choisir deux dates précises pour montrer une évolution peut…','cacher une tendance différente sur une période plus large',['toujours donner une vision complète et honnête','être interdit par la loi','n’avoir aucune influence sur la perception'],'Le choix de la période influence fortement l’impression donnée.'],
   ['Une moyenne peut-elle cacher de grandes différences entre les cas individuels ?','oui',['non, jamais','non, une moyenne montre toujours tous les cas en détail','non, c’est impossible mathématiquement'],'Deux groupes très différents peuvent avoir la même moyenne.'],
   ['Avant de croire un chiffre présenté dans un article, il est utile de vérifier…','la source et la période sur laquelle il porte',['uniquement la couleur du graphique','uniquement la taille de la police utilisée','rien, un chiffre est toujours exact'],'Ces éléments permettent de juger sa pertinence.'],
   {tf:'Un chiffre exact peut être présenté de façon trompeuse selon son contexte et sa mise en forme.',v:true,e:'La présentation peut exagérer ou minimiser sans changer le chiffre lui-même.'},
   {tf:'Tous les graphiques présentés dans les médias utilisent systématiquement une échelle qui commence à zéro.',v:false,e:'Certains utilisent des échelles tronquées, intentionnellement ou non.',d:2}]),2])},

{id:'emi3d',name:'IA générative et information',icon:'🤖',domain:'Intelligence artificielle',
 refs:[REF_CLEMI+' — culture technique et numérique',EDU],
 tip:'Une IA générative peut créer un texte, une image ou une voix très convaincants mais entièrement faux (hypertrucage ou « deepfake ») : la vérification de la source reste indispensable, même face à un contenu qui paraît très réaliste.',
 c:C(`Les <b>intelligences artificielles génératives</b> peuvent produire des textes, des images, des voix et des vidéos très réalistes. Cette capacité pose de nouveaux défis pour l’éducation aux médias et à l’information : comment distinguer un contenu authentique d’un contenu généré ou truqué ?`,
  [T('Contenus générés et hypertrucages',`<p>Un <b>hypertrucage</b> (deepfake) est une image, une vidéo ou un son créés ou modifiés par IA pour faire croire qu’une personne a dit ou fait quelque chose qu’elle n’a pas réellement dit ou fait. Une IA peut aussi générer un <b>texte</b> entier, avec de fausses citations ou de fausses sources (« hallucinations »), présenté de façon très convaincante.</p>`),
   T('Vérifier malgré le réalisme',`<p>Un contenu généré par IA peut présenter des <b>indices</b> (détails incohérents, mouvements bizarres sur une vidéo), mais ces indices deviennent de plus en plus difficiles à repérer. La méthode reste la même : vérifier la <b>source</b>, chercher une <b>confirmation</b> indépendante, se méfier d’un contenu surprenant même s’il paraît très réaliste.</p>`)],
  [{q:'Une vidéo semble montrer une personnalité publique annonçant une décision surprenante.',s:['Vérifier si des médias reconnus confirment cette annonce.','Chercher si la personnalité ou son entourage l’a démentie ou confirmée.','Se méfier, car une vidéo très réaliste peut être un hypertrucage.']}],
  ['Je sais ce qu’est un hypertrucage (deepfake).','Je comprends qu’une IA peut générer du texte avec de fausses informations (« hallucinations »).','Je vérifie une source même quand un contenu semble très réaliste.','Je cherche une confirmation indépendante avant de croire un contenu surprenant.'],
  ['Croire qu’un contenu réaliste est automatiquement authentique.','Partager une vidéo surprenante sans vérifier sa source.','Faire une confiance totale à une réponse d’IA sans vérifier les faits cités.'],
  ['Hypertrucage = image/son/vidéo truqués par IA.','IA générative de texte : peut inventer (« hallucinations »).','Vérifier la source malgré le réalisme apparent.']),
 g:mix([bank([
  ['Un hypertrucage (deepfake) est…','un contenu (image, son, vidéo) créé ou modifié par IA pour tromper sur ce qu’une personne a dit ou fait',['une simple photo retouchée avec un filtre de couleur','un type de virus informatique','un format de fichier audio'],'Il peut être très difficile à distinguer d’un contenu authentique.'],
  ['Une « hallucination » d’IA générative de texte désigne…','une information inventée, présentée de façon convaincante comme vraie',['un bug d’affichage de l’écran','un contenu toujours signalé comme faux par l’IA elle-même','une fonctionnalité impossible à produire'],'L’IA peut inventer des citations ou des sources qui n’existent pas.'],
  ['Face à une vidéo surprenante impliquant une personnalité connue, la bonne pratique est…','de vérifier si des médias reconnus la confirment avant de la croire',['de la partager immédiatement car elle semble réelle','de supposer qu’elle est forcément authentique','de l’ignorer sans aucune vérification'],'Le réalisme visuel ne garantit pas l’authenticité.'],
  ['Les indices qui permettent de repérer un hypertrucage sont-ils toujours faciles à voir ?','non, ils deviennent de plus en plus difficiles à repérer',['oui, toujours évidents','oui, une simple observation suffit toujours','oui, car les IA ne progressent jamais'],'La technologie progresse rapidement, rendant les détections plus difficiles.',2],
  ['Pourquoi la méthode de vérification (source, recoupement) reste-t-elle utile face à l’IA générative ?','parce qu’elle permet de vérifier l’authenticité indépendamment du réalisme apparent',['parce qu’elle n’a plus aucune utilité','parce que l’IA ne peut jamais tromper','parce que seule l’apparence compte'],'Le fond (vérification) compte plus que la forme (réalisme visuel).',2],
  {tf:'Un contenu généré par IA peut sembler très convaincant tout en étant entièrement faux.',v:true,e:'Le réalisme technique ne garantit pas l’exactitude du contenu.'},
  {tf:'Toute information donnée par une IA conversationnelle est vérifiée avant d’être affichée.',v:false,e:'Une IA générative peut produire des erreurs ou des informations inventées sans le signaler systématiquement.',d:2},
  ['Demander à une IA générative de citer ses sources garantit-elle que ces sources existent réellement ?','non, l’IA peut aussi inventer de fausses sources de façon convaincante',['oui, toujours de façon certaine','oui, une IA ne peut jamais inventer une source','oui, car la loi l’impose à toutes les IA'],'Une « hallucination » peut aussi concerner une source citée.',2],
  ['Un son généré par IA imitant la voix d’une personne peut-il tromper même des proches de cette personne ?','oui, les technologies récentes rendent certaines imitations très convaincantes',['non, jamais','non, la voix humaine est impossible à reproduire par IA','non, cela ne concerne que les images'],'Le clonage vocal par IA progresse rapidement.',3],
  ['Face à un contenu dont on n’arrive pas à déterminer avec certitude s’il est généré par IA ou authentique, la bonne attitude est…','de suspendre son jugement et chercher une confirmation avant de le croire ou de le partager',['de le croire par défaut','de le rejeter systématiquement sans vérification','de décider au hasard'],'Le doute justifie la prudence plutôt qu’une conclusion hâtive.'],
  ['Certains outils cherchent à détecter si une image ou une vidéo a été générée par IA. Sont-ils toujours fiables à 100 % ?','non, ils peuvent se tromper, dans un sens comme dans l’autre',['oui, toujours fiables à 100 %','oui, car l’IA ne peut jamais tromper un autre outil','oui, car ce sont des outils officiels infaillibles'],'Ces outils restent une aide, pas une garantie absolue.',3],
  ['Un texte rédigé entièrement par une IA générative et présenté sans aucune mention comme le travail personnel d’un élève pose-t-il un problème d’honnêteté ?','oui, cela peut constituer une tromperie sur l’origine réelle du travail',['non, aucun problème particulier','non, car l’IA appartient à tout le monde','non, tant que le texte est correct'],'La transparence sur l’usage d’une IA fait partie de l’honnêteté intellectuelle.',2]]),2])},

{id:'emi3e',name:'Pluralisme, liberté de la presse et démocratie',icon:'🗳️',domain:'Citoyenneté',
 refs:[REF_CLEMI+' — culture sociale et citoyenne',LOI1881,EDU],
 tip:'Le pluralisme des médias — plusieurs médias indépendants, avec des lignes éditoriales différentes — permet aux citoyens de comparer les points de vue plutôt que de dépendre d’une seule source d’information.',
 c:C(`La diversité des médias, ou <b>pluralisme</b>, et la <b>liberté de la presse</b> sont des conditions essentielles d’une <b>démocratie</b> : elles permettent aux citoyens de s’informer de façon indépendante, de comparer les points de vue et de former leur propre jugement.`,
  [T('Le pluralisme des médias',`<p>Le <b>pluralisme</b> désigne l’existence de plusieurs médias <b>indépendants</b>, avec des lignes éditoriales différentes, qui permettent de confronter les points de vue sur un même sujet. En France, des règles existent pour favoriser ce pluralisme (concentration des médias limitée, aides à la presse). À l’inverse, dans des pays où l’État contrôle tous les médias, le pluralisme est très réduit.</p>`),
   T('Pourquoi c’est essentiel à la démocratie',`<p>Une presse <b>libre</b> et <b>plurielle</b> permet de contrôler l’action des pouvoirs publics (c’est pourquoi on l’appelle parfois le « <b>quatrième pouvoir</b> »), de révéler des informations d’intérêt public, et de donner aux citoyens les éléments pour voter et débattre en connaissance de cause. Attaquer ou museler la presse est souvent l’une des premières étapes d’un recul démocratique.</p>`)],
  [{q:'Dans un pays, un seul média, contrôlé par l’État, diffuse l’information. Quelles conséquences pour les citoyens ?',s:['Ils ne peuvent pas comparer différents points de vue.','L’absence de pluralisme limite leur capacité à se forger un jugement indépendant.','C’est contraire au principe démocratique d’une presse libre et plurielle.']}],
  ['Je comprends ce qu’est le pluralisme des médias.','Je sais pourquoi la liberté de la presse est liée à la démocratie.','Je comprends l’expression « quatrième pouvoir ».','Je repère un recul du pluralisme ou de la liberté de la presse.'],
  ['Croire qu’un seul média suffit à bien s’informer.','Penser que la liberté de la presse n’a aucun lien avec la démocratie.','Ignorer les atteintes à la liberté de la presse dans certains pays.'],
  ['Pluralisme = plusieurs médias indépendants.','Presse = « quatrième pouvoir ».','Lien direct entre liberté de la presse et démocratie.']),
 g:mix([bank([
  ['Le pluralisme des médias désigne…','l’existence de plusieurs médias indépendants, aux lignes éditoriales différentes',['un seul média très populaire','l’absence totale de journaux','une loi sur l’orthographe'],'Il permet de comparer différents points de vue.'],
  ['Pourquoi appelle-t-on parfois la presse le « quatrième pouvoir » ?','parce qu’elle peut contrôler et informer sur l’action des pouvoirs publics',['parce qu’elle vote les lois','parce qu’elle nomme le gouvernement','parce qu’elle rend la justice'],'Elle complète les pouvoirs législatif, exécutif et judiciaire sans en être un.',2],
  ['Dans un pays où un seul média, contrôlé par l’État, diffuse l’information, le pluralisme est…','très réduit ou inexistant',['particulièrement développé','sans aucun lien avec ce fait','identique à celui d’une démocratie avec plusieurs médias'],'Un seul point de vue officiel domine alors l’information disponible.'],
  ['Museler ou attaquer la presse libre dans un pays est souvent considéré comme…','un signe de recul démocratique',['un signe de bonne santé démocratique','sans aucune conséquence politique','une pratique sans lien avec la démocratie'],'La liberté de la presse est un indicateur suivi par des organisations internationales.',2],
  ['Pourquoi la diversité des médias aide-t-elle les citoyens à voter en connaissance de cause ?','elle leur permet de comparer plusieurs analyses d’un même sujet',['elle complique uniquement leur choix sans aucun bénéfice','elle n’a aucun lien avec le vote','elle remplace le vote lui-même'],'Comparer plusieurs sources enrichit le jugement personnel.'],
  {tf:'La liberté de la presse permet de révéler des informations d’intérêt public, parfois gênantes pour des personnes puissantes.',v:true,e:'C’est l’une de ses fonctions démocratiques essentielles.'},
  {tf:'Le pluralisme des médias signifie que tous les médias doivent dire exactement la même chose.',v:false,e:'Il signifie au contraire la coexistence de points de vue différents et indépendants.'},
  ['Des organisations internationales publient des classements sur la liberté de la presse dans le monde. À quoi servent-ils ?','à comparer et suivre l’état de cette liberté selon les pays',['à fixer le prix des journaux','à sélectionner les meilleurs journalistes','à organiser des élections'],'Ils permettent de documenter les évolutions, positives ou négatives.',2],
  ['Un gouvernement qui ferme les médias d’opposition agit-il dans le sens du pluralisme ?','non, cela réduit la diversité des sources d’information disponibles',['oui, cela renforce toujours le pluralisme','oui, car cela simplifie l’information','oui, cela n’a aucun effet sur le pluralisme'],'Réduire le nombre de médias indépendants va à l’encontre du pluralisme.'],
  ['La concentration d’un grand nombre de médias dans les mains d’un très petit nombre de propriétaires peut-elle fragiliser le pluralisme ?','oui, elle peut réduire la diversité réelle des lignes éditoriales',['non, cela n’a aucun effet','non, cela renforce toujours la diversité','non, un seul propriétaire garantit plus d’indépendance'],'Des règles existent en France pour limiter certaines concentrations.',2],
  ['Un citoyen qui s’informe uniquement auprès d’une seule source, jamais confrontée à d’autres points de vue, bénéficie-t-il pleinement du pluralisme existant ?','non, le pluralisme n’est utile que si le citoyen compare effectivement plusieurs sources',['oui, automatiquement, dès qu’il existe plusieurs médias dans le pays','oui, peu importe ses propres habitudes de lecture','oui, le pluralisme ne dépend jamais des choix individuels'],'Le pluralisme offre une possibilité que chacun doit ensuite exercer.',3],
  ['La protection du secret des sources permet notamment à un journaliste de…','recueillir des témoignages de personnes qui craindraient des représailles si elles étaient identifiées',['publier n’importe quelle information sans vérification','échapper à toute règle déontologique','être rémunéré davantage'],'Elle favorise la liberté d’informer sur des sujets sensibles.',3]]),2])},

{id:'emi3f',name:'Produire une information argumentée et sourcée',icon:'📝',domain:'Publication',
 refs:[REF_CLEMI+' — culture médiatique et informationnelle',CPI,EDU],
 tip:'Un article argumenté et sourcé présente des faits vérifiés, cite précisément ses sources, et distingue clairement les faits des opinions (y compris celle de l’auteur, si elle est exprimée).',
 c:C(`En 3e, produire une information ne se limite plus à rapporter un fait : il s’agit de construire un <b>article argumenté</b>, qui présente des faits vérifiés, les met en perspective, et cite précisément ses <b>sources</b>, dans le respect du <b>droit d’auteur</b> et de la déontologie journalistique.`,
  [T('Construire un article argumenté',`<p>Un article argumenté présente une <b>problématique</b> claire, rassemble des <b>faits vérifiés</b> issus de sources fiables, et peut présenter différents <b>points de vue</b> sur un sujet controversé, sans les confondre avec des faits établis. Si l’auteur exprime une opinion, elle est clairement signalée comme telle (éditorial, tribune, chronique).</p>`),
   T('Citer et respecter les droits',`<p>Chaque fait avancé doit pouvoir être relié à une <b>source</b> (« selon… », note de bas de page, lien). Les images, citations ou extraits utilisés respectent le <b>droit d’auteur</b> : citation courte avec mention de la source, ou usage autorisé par une licence. Le non-respect de ces règles peut constituer du <b>plagiat</b> ou une violation des droits d’auteur.</p>`)],
  [{q:'Rédige le début d’un article sur l’impact d’un projet d’aménagement local.',s:['Problématique claire : quels sont les arguments pour et contre ce projet ?','Faits vérifiés : budget annoncé, date de début des travaux, source officielle citée.','Points de vue des différents acteurs (habitants, élus, associations) présentés et distingués des faits.']}],
  ['Je formule une problématique claire.','Je distingue faits vérifiés et points de vue.','Je cite mes sources précisément.','Je respecte le droit d’auteur pour les citations, images et extraits utilisés.'],
  ['Présenter une opinion personnelle comme si c’était un fait établi.','Oublier de citer la source d’un chiffre ou d’une citation.','Recopier un extrait sans en mentionner l’auteur (plagiat).'],
  ['Problématique, faits vérifiés, points de vue distincts.','Citer précisément ses sources.','Respect du droit d’auteur : pas de plagiat.']),
 g:mix([bank([
  ['Une « tribune » ou un « éditorial » dans un journal présente généralement…','l’opinion personnelle et signalée comme telle de son auteur',['uniquement des faits neutres sans aucun avis','la position officielle du gouvernement','un simple compte rendu d’agence de presse'],'Ce type de texte est clairement distingué des articles d’information.',2],
  ['Le plagiat consiste à…','recopier le travail de quelqu’un d’autre sans le citer, en le présentant comme le sien',['citer correctement une source','résumer un article en indiquant son origine','critiquer un texte avec ses propres mots'],'C’est une violation du droit d’auteur et de l’honnêteté intellectuelle.'],
  ['Présenter plusieurs points de vue sur un sujet controversé, sans les confondre avec des faits établis, est…','une pratique rigoureuse d’un article argumenté',['toujours interdit dans un article','une preuve de malhonnêteté','sans intérêt pour le lecteur'],'Cela aide le lecteur à se forger son propre jugement.'],
  ['Pour citer une courte phrase tirée d’un livre dans son article, il faut…','en mentionner l’auteur et l’œuvre d’origine',['la présenter comme ses propres mots','la modifier pour qu’elle ne soit plus reconnaissable','rien, les livres ne sont jamais protégés'],'La citation doit être attribuée à son auteur.'],
  ['Une problématique claire au début d’un article sert à…','orienter la lecture vers la question traitée par l’article',['remplacer entièrement le contenu de l’article','cacher les sources utilisées','éviter de devoir vérifier les faits'],'Elle structure la réflexion du lecteur.'],
  {tf:'Un article argumenté peut présenter des points de vue différents tout en restant rigoureux, à condition de les distinguer des faits établis.',v:true,e:'La nuance et la rigueur ne s’opposent pas.'},
  {tf:'Citer précisément ses sources dans un article alourdit inutilement le texte et devrait être évité.',v:false,e:'Au contraire, cela renforce la crédibilité et permet au lecteur de vérifier.'},
  ['Reformuler une idée tirée d’un article en indiquant sa source est-il considéré comme du plagiat ?','non, c’est une pratique normale de citation des sources',['oui, systématiquement','oui, car reformuler ne change rien','oui, dès qu’on utilise l’idée d’un autre'],'Le plagiat suppose de ne pas créditer l’origine de l’idée ou du texte.',2],
  ['Un article qui ne cite aucune source pour des chiffres précis avancés est-il aussi crédible qu’un article qui les source clairement ?','non, l’absence de source rend les chiffres plus difficiles à vérifier',['oui, exactement aussi crédible','oui, les sources n’ont aucune importance','oui, un chiffre est toujours vrai en lui-même'],'La traçabilité des informations est un critère de qualité.'],
  ['Relire et vérifier un article avant publication fait-il partie d’une démarche d’information responsable ?','oui, cela permet de corriger les erreurs et d’ajuster le ton employé',['non, cela ralentit inutilement la publication','non, un premier jet est toujours suffisant','non, seule la rapidité compte'],'La relecture améliore la qualité et la fiabilité du contenu produit.'],
  ['Présenter un point de vue minoritaire sur un sujet, à côté des points de vue majoritaires, dans un article argumenté, est…','une pratique qui peut enrichir la compréhension du lecteur, si elle est clairement identifiée comme telle',['toujours interdit dans un article rigoureux','une erreur à éviter systématiquement','une obligation de lui donner autant de place qu’au reste'],'La rigueur n’exclut pas la diversité des points de vue, à condition de les distinguer des faits établis.',3],
  ['Indiquer clairement la date de publication d’un article en ligne, de façon visible, fait-il partie d’une publication responsable ?','oui, cela permet au lecteur de juger si l’information est encore d’actualité',['non, la date n’a aucune utilité','non, cela ne concerne que les articles imprimés','non, seul le contenu compte, jamais la date'],'Un article non daté peut être repris à tort comme récent plus tard.']]),2])}
]);

})();
